insert into private.study_guides (guide, chunks, sha256) values ('study_guide_acs101', 33, '9d1fbab5d21fbe30ad5178bd6b28f4e4bd0606c00152ff55781703261ef72ae4');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 1, $study_guide${"guide":"study_guide_acs101","code":"ACS101","courseId":"d1b6b70d-037b-5e9e-a4d4-17103525cc56","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"6551688f-134a-5749-ae36-c57db4119ee8","create":true,"after":{"title":"Introduction to Actuarial Science","body":"Every topic is examinable.","outcomes":["Describe the relationship between actuarial science and insurance.","Define the various actuarial symbols.","Explain the dynamic role of actuarial science as a discipline.","Identify the various career choices for an actuary.","Solve simple and compound interest problems.","Explain the different features of a life table.","Define the different types of annuities and state their formulae."],"assessment":["The exam is objective (CBT), with some theory questions. Expect definitions, history, actuarial symbols, life-table values and calculations.","Calculations come from Topics 3, 5, 6 and 7. Practise the formulas until you can do them quickly."]}},"retire":[],"notes":[{"kind":"note","itemId":"379e87b6-544b-566a-ba52-5342f8b2a19d","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Nature of Actuarial Science and the Actuary","body":"The definitions of actuarial science and an actuary; risk, uncertainty and contingent events; probability, expected value, the law of large numbers and pooling; what actuaries do and how they model; where actuaries work; the skills needed; how actuaries differ from accountants, statisticians and CFAs.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"The definitions of actuarial science and an actuary; risk, uncertainty and contingent events; probability, expected value, the law of large numbers and pooling; what actuaries do and how they model; where actuaries work; the skills needed; how actuaries differ from accountants, statisticians and CFAs."}],"lessons":[{"number":"1.1","title":"What actuarial science is and who an actuary is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial science:","bold":true},{"text":" deals with evaluating risks and maintaining the "},{"text":"economic stability","bold":true},{"text":" of insurance or financial organisations. Graduates learn to use "},{"text":"mathematics, statistics and probability","bold":true},{"text":" principles to "},{"text":"anticipate future events and take preventive measures","bold":true},{"text":". In short, it is concerned with the "},{"text":"financial consequences of uncertain future events","bold":true},{"text":"."}]},{"text":[{"text":"Main goal of actuarial studies:","bold":true},{"text":" to build the knowledge needed to do an actuary's job and to prepare students to pass their actuarial exams faster."}]},{"text":[{"text":"Actuary (standard definition):","bold":true},{"text":" a person who applies "},{"text":"mathematical approaches to anticipate, measure and manage risk","bold":true},{"text":"."}]},{"text":[{"text":"Other definitions you must recognise:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A business professional who manages "},{"text":"financial risk","bold":true},{"text":" related to insurance product design, pensions and other financial corporate planning."}]},{"text":[{"text":"By applying probability, statistics, risk theory and financial principles, an actuary is able to "},{"text":"quantify","bold":true},{"text":" future risk in insurance, annuity and pension programmes."}]}]}]},{"text":[{"text":"An actuary:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Analyses, manages and measures the financial implications of future risk."}]},{"text":[{"text":"Develops and validates financial models to guide decision making."}]},{"text":[{"text":"Serves as the "},{"text":"analytical backbone","bold":true},{"text":" of society's financial security programmes ("},{"text":"insurance, social security, pensions","bold":true},{"text":")."}]}]}]},{"text":[{"text":"Disciplines drawn on:","bold":true},{"text":" probability, statistics, economics, finance and computer science."}]},{"text":[{"text":"Origin of the word:","bold":true},{"text":" Latin "},{"text":"actuarius","bold":true},{"text":", a Roman clerk who kept records and accounts."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Part super-hero, part fortune-teller, part trusted advisor.\"","bold":true},{"text":" The fortune-teller part is evaluating the likelihood of future events "},{"text":"using numbers, not crystal balls","bold":true},{"text":". Actuaries are experts in three things:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Evaluating the likelihood of future events."}]},{"text":[{"text":"Designing creative ways to reduce the likelihood of undesirable events."}]},{"text":[{"text":"Decreasing the impact of undesirable events that do occur."}]}]},{"type":"paragraph","text":[{"text":"\"Guaranteeing that undesirable events never occur\" is "},{"text":"not","bold":true},{"text":" one of them: no one can promise that."}]}]},{"text":[{"text":"As "},{"text":"problem solvers and strategic thinkers","bold":true},{"text":", actuaries measure the probability and risk of future events and predict their financial impact on a business and its clients."}]},{"text":[{"text":"Rear-view mirror:","bold":true},{"text":" an actuary typically uses "},{"text":"data from the past to predict the future","bold":true},{"text":", like driving by looking in the rear-view mirror, so must also "},{"text":"quantify how the future will be different from the past","bold":true},{"text":". A sharp rise in petrol prices changes motor insurance costs, so last year's claims are not simply copied forward."}]},{"text":[{"text":"Main challenge:","bold":true},{"text":" there is "},{"text":"no past data","bold":true},{"text":", or the data is "},{"text":"no longer relevant","bold":true},{"text":" because of policy or other changes."}]},{"text":[{"text":"Match the discipline to the task: e$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 2, $study_guide$stimating death rates from past records is "},{"text":"statistics","bold":true},{"text":"; processing two million records and running simulations is "},{"text":"computer science","bold":true},{"text":"; asking how Nigerian inflation, interest rates and unemployment affect claims and returns is "},{"text":"economics","bold":true},{"text":"."}]}]}]},{"number":"1.2","title":"Risk, uncertainty and contingent events","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Risk:","bold":true},{"text":" (1) the "},{"text":"possibility of failing to meet objectives","bold":true},{"text":"; (2) it "},{"text":"can only be defined in context","bold":true},{"text":": a risk to one person or entity may not be a risk to another."}]},{"text":[{"text":"Uncertainty:","bold":true},{"text":" a situation that involves "},{"text":"imperfect or unknown information","bold":true},{"text":". It applies to predictions of future events, to measurements already made, or to the unknown. It is also called "},{"text":"unmeasurable risk","bold":true},{"text":"."}]},{"text":[{"text":"Actuarial risk:","bold":true},{"text":" a phenomenon subject to uncertainty in one or more of "},{"text":"3 variables: occurrence, timing and severity","bold":true},{"text":"."}]},{"text":[{"text":"Contingency:","bold":true},{"text":" an "},{"text":"event that may or may not occur","bold":true},{"text":". (It can also mean cash held for emergencies, or a condition that must be met for a contract to be binding.)"}]},{"text":[{"text":"Contingent:","bold":true},{"text":" an economic benefit that depends on an event whose occurrence or timing is not certain."}]},{"text":[{"text":"Hazard:","bold":true},{"text":" a condition that "},{"text":"increases the probability or expected size","bold":true},{"text":" of a loss."}]},{"text":[{"text":"Peril:","bold":true},{"text":" the "},{"text":"probable cause","bold":true},{"text":" (fire, flood, earthquake, theft) that exposes a person or property to loss, and against which insurance is bought."}]},{"text":[{"text":"Risk factor:","bold":true},{"text":" any attribute, characteristic or exposure that increases the likelihood of a future loss."}]},{"text":[{"text":"Mortality:","bold":true},{"text":" the incidence of "},{"text":"death","bold":true},{"text":" in a population, often measured by the probability that a randomly selected person "},{"text":"dies","bold":true},{"text":" within a period."}]},{"text":[{"text":"Morbidity:","bold":true},{"text":" the rate of "},{"text":"disease","bold":true},{"text":" in a population, often measured by the probability that a randomly selected person "},{"text":"becomes seriously ill","bold":true},{"text":" within a period."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Risk versus uncertainty:","bold":true},{"text":" under risk, the chances of outcomes "},{"text":"can be measured","bold":true},{"text":"; under uncertainty they "},{"text":"cannot","bold":true},{"text":"."}]},{"text":[{"text":"Risk in context:","bold":true},{"text":" heavy rain threatens a Benue farmer's crops but is no concern to a Lagos software company."}]},{"text":[{"text":"Which variable is uncertain?","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Whole life policy paying ₦2,000,000 whenever Mr Okonkwo dies: death is certain and the amount is fixed, so only the "},{"text":"timing","bold":true},{"text":" is uncertain."}]},{"text":[{"text":"Motor cover in Abuja: the insurer does not know whether the car will crash ("},{"text":"occurrence","bold":true},{"text":") or how much repairs would cost ("},{"text":"severity","bold":true},{"text":")."}]},{"text":[{"text":"\"Ownership\" is "},{"text":"not","bold":true},{"text":" an actuarial risk variable."}]}]}]},{"text":[{"text":"A policy paying ₦1,000,000 only if Mrs Adebayo dies within 10 years is "},{"text":"contingent","bold":true},{"text":": it depends on an uncertain event. A fixed amount does not make it certain."}]},{"text":[{"text":"Trap:","bold":true},{"text":" fire is the "},{"text":"peril","bold":true},{"text":"; the faulty wiring in a Kano warehouse is the "},{"text":"hazard","bold":true},{"text":". Do not swap them."}]},{"text":[{"text":"Trap:","bold":true},{"text":" mortality is death; morbidity is illness."}]}]}]},{"number":"1.3","title":"Probability, expected value, pooling and insurance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Probability","bold":true},{"text":" measures the likelihood that an event occurs. It always lies "},{"text":"from 0 to 1","bold":true},{"text":" inclusive (0 = impossible, 1 = certain). A value such as 1.2 or a negative value can "},{"text":"never","bold":true},{"text":" be a probability."}]},{"text":[{"text":"Expected value:","bold":true},{"text":" the "},{"text":"probability-weighted average","bold":true},{"text":" of the values taken by a random variable."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"E(X) = x_1 × p_1 + x_2 × p_2 + ... + x_k × p_k"}]},{"text":[{"text":"Expected claim cost per policy = probability of a claim × average claim amount"}]},{"text":[{"text":"Total expected claims = number of policies × expected claim cost per policy"}]}]}]},{"text":[{"text":"Law of large numbers:","bold":true},{"text":" as the number of independent, similar trials increases, the observed proportion of an event becomes "},{"text":"more stable","bold":true},{"text":". Larger groups give more certain predictions."}]},{"text":[{"text":"Statistical regularity:","bold":true},{"text":" random events show regular patterns when repeated enough times, or when there are enough similar events. It is an umbrella term covering the law of large numbers."}]},{"text":[{"text":"Pooling:","bold":true},{"text":" forming a group of policies with "},{"text":"similar characteristics","bold":true},{"text":", so that an insurer can manage individual risks by "},{"text":"reducing the variability (variance)","bold":t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 3, $study_guide$rue},{"text":" of total outcomes. A good pool is (1) "},{"text":"large","bold":true},{"text":", (2) "},{"text":"similar (homogeneous)","bold":true},{"text":", (3) with losses "},{"text":"reasonably independent","bold":true},{"text":"."}]},{"text":[{"text":"Risk aversion:","bold":true},{"text":" preferring a "},{"text":"small certain loss","bold":true},{"text":" (the premium) to a "},{"text":"large uncertain one","bold":true},{"text":". Because risk-averse people will pay "},{"text":"above their expected loss","bold":true},{"text":", the insurer can "},{"text":"cover its expenses and make a profit","bold":true},{"text":"."}]},{"text":[{"text":"Insurable risk","bold":true},{"text":" has:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A potential loss"}]},{"text":[{"text":"that is significant and important;"}]},{"text":[{"text":"a loss and economic value that are well defined and "},{"text":"out of the policyholder's complete control","bold":true},{"text":";"}]},{"text":[{"text":"covered losses that are reasonably independent."}]}]},{"type":"paragraph","text":[{"text":"It must also not be so large that no insurer could pay for it."}]}]},{"text":[{"text":"Financial security system:","bold":true},{"text":" an arrangement in which one party assumes the obligation to provide benefits that offset undesirable economic consequences suffered by a second party, in return for payments called "},{"text":"considerations","bold":true},{"text":". Examples: insurance products and retirement plans."}]},{"text":[{"text":"Experience:","bold":true},{"text":" the data obtained from the actual operation of an insurance or pension scheme."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example 1 (expected loss).","bold":true},{"text":" An Onitsha shop has a 0.4% chance of a fire in a year, with a loss of ₦5,000,000 if it happens, and nil otherwise."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Step 1: 0.4% = 0.004."}]},{"text":[{"text":"Step 2: E(loss) = 0.004 × ₦5,000,000 + 0.996 × ₦0 = "},{"text":"₦20,000","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Worked example 2 (expected claim per policy).","bold":true},{"text":" An insurer covers 10,000 buses; 3% have an accident each year; the average claim is ₦400,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Per bus: 0.03 × ₦400,000 = "},{"text":"₦12,000","bold":true},{"text":"."}]},{"text":[{"text":"Whole portfolio: 10,000 × ₦12,000 = ₦120,000,000. \"Per bus\" wants ₦12,000."}]}]}]},{"text":[{"text":"Risk aversion in figures.","bold":true},{"text":" An Aba trader faces a 0.5% chance of losing ₦3,000,000. Her expected loss is 0.005 × ₦3,000,000 = ₦15,000, yet she gladly pays a ₦30,000 premium. The extra ₦15,000 is what lets the insurer cover expenses and earn a profit."}]},{"text":[{"text":"Law of large numbers in practice.","bold":true},{"text":" Insurer B with 50,000 similar okada riders predicts total claims more reliably than Insurer A with 50, because larger similar groups give more stable proportions."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a pool whose members are \"as different as possible\" is "},{"text":"not","bold":true},{"text":" desirable. "},{"text":"Trap:","bold":true},{"text":" a loss fully under the policyholder's control is "},{"text":"not","bold":true},{"text":" insurable."}]}]}]},{"number":"1.4","title":"What actuaries do and how they work","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The actuary","bold":true},{"text":" identifies, analyses and documents risks; monitors risk areas; defines problems and generates ideas; develops recommendations that lead to implemented solutions; and "},{"text":"continuously monitors results","bold":true},{"text":"."}]},{"text":[{"text":"An actuary's work is based on "},{"text":"theory, data and experience","bold":true},{"text":" and is performed with "},{"text":"professional judgement","bold":true},{"text":", which is needed because tasks affect "},{"text":"several stakeholders with different, sometimes conflicting, needs","bold":true},{"text":"."}]},{"text":[{"text":"What actuaries do:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Evaluate the likelihood of future events:","bold":true},{"text":" forecast the impact of catastrophes; calculate the expected lifetime of a retiree receiving a pension."}]},{"text":[{"text":"Design ways to reduce the likelihood of undesirable events:","bold":true},{"text":" life insurance policies, annuities; promote safety (seat belts)."}]},{"text":[{"text":"Decrease the impact of undesirable events that occur:","bold":true},{"text":" death benefits, retirement benefits, indemnity benefits."}]},{"text":[{"text":"Participate in corporate planning:","bold":true},{"text":" mergers and acquisitions; evaluating investment programmes."}]},{"text":[{"text":"Help insurance companies:","bold":true},{"text":" calculate rates for new products; forecast and interpret underwriting results; maintain databases for analysing pricing issues."}]}]}]},{"text":[{"text":"Further value:","bold":true},{"text":" products meeting customers' needs "},{"text":"now and in the future","bold":true},{"text":"; expertise in "},{"text":"data quality and analytics","bold":true},{"text":"; "},{"text":"predictive modelling and optimisation","bold":true},{"text":" for smarter risk decisions in digital businesses; supporting "},{"text":"marketing","bold":true},{"text":" (modelling demand for a new product), "},{"text":"accounting","bold":true},{"text":" (models and assumptions for "},{"text":"budgeting and forecasting","bold":true},{"text":"), "},{"text":"product development","bold":true},{"text":", and "},{"text":"identifying and managing risk","bold":true},{"text":"."}]},{"text":[{"text":"Key terms:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial model:","bold":true$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 4, $study_guide$},{"text":" a "},{"text":"simplified representation","bold":true},{"text":" of real-world relationships, used to explain a system, derive estimates and guide decisions."}]},{"text":[{"text":"3 components:","bold":true},{"text":" "},{"text":"input","bold":true},{"text":" (delivers assumptions, parameters and data), "},{"text":"processing","bold":true},{"text":" (transforms inputs into estimates), "},{"text":"output","bold":true},{"text":" (translates estimates into useful business information)."}]},{"text":[{"text":"Life cycle, 3 phases:","bold":true},{"text":" "},{"text":"specification","bold":true},{"text":", "},{"text":"implementation","bold":true},{"text":", "},{"text":"production","bold":true},{"text":" (one or more model runs)."}]},{"text":[{"text":"Actuarial assumption:","bold":true},{"text":" an estimate of an uncertain variable fed into a model, normally to calculate premiums or benefits."}]},{"text":[{"text":"Deterministic model:","bold":true},{"text":" one fixed set of assumptions, events assumed to happen with certainty, giving a single result."}]},{"text":[{"text":"Stochastic model:","bold":true},{"text":" estimates "},{"text":"probability distributions","bold":true},{"text":" of outcomes by letting one or more inputs vary randomly."}]},{"text":[{"text":"Best estimate:","bold":true},{"text":" neither optimistic nor conservative."}]},{"text":[{"text":"Scenario:","bold":true},{"text":" a set of assumptions about future conditions, based on professional judgement or prescribed by law."}]},{"text":[{"text":"Actuarial control cycle:","bold":true},{"text":" "},{"text":"define the problem → design the solution → monitor the results","bold":true},{"text":"."}]},{"text":[{"text":"Pricing:","bold":true},{"text":" developing premiums to cover losses from underwritten risks and future benefits, using probabilities of loss."}]},{"text":[{"text":"Reserve:","bold":true},{"text":" a liability set aside to pay "},{"text":"future claims","bold":true},{"text":"."}]},{"text":[{"text":"In short, actuaries "},{"text":"analyse past data","bold":true},{"text":" to work out how much money should be "},{"text":"set aside to cover financial losses that could occur in the future","bold":true},{"text":"."}]},{"text":[{"text":"Valuation:","bold":true},{"text":" placing a value on an insurer's assets and/or liabilities."}]},{"text":[{"text":"Risk management:","bold":true},{"text":" identifying and measuring risk, then developing strategies to minimise, monitor and control it. Handle first the risks with the "},{"text":"greatest loss and greatest probability","bold":true},{"text":"."}]},{"text":[{"text":"Risk transfer:","bold":true},{"text":" shifting risk to another party (for example, paying an insurer a premium). "},{"text":"Risk retention:","bold":true},{"text":" keeping the risk yourself (self-insurance, deductibles)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Matching tasks to categories:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Seat-belt campaign by a Lagos motor insurer's actuary: "},{"text":"reducing the likelihood","bold":true},{"text":" of undesirable events."}]},{"text":[{"text":"Monthly pension to a retired Ibadan civil servant, death benefit to a family: "},{"text":"decreasing the impact","bold":true},{"text":" of events that occur."}]},{"text":[{"text":"Estimating how long a pensioner will draw a pension, forecasting flood costs: "},{"text":"evaluating the likelihood","bold":true},{"text":" of future events."}]},{"text":[{"text":"Assessing a bank merger and investment programmes: "},{"text":"corporate planning","bold":true},{"text":"."}]},{"text":[{"text":"Acting as the insurer's lawyer is "},{"text":"not","bold":true},{"text":" an actuarial task; nor is ignoring results after a solution is in place."}]}]}]},{"text":[{"text":"The Lagos car-accident method.","bold":true},{"text":" To predict accidents in Lagos this November, the actuary first looks at the "},{"text":"percentage of people involved in accidents in previous years","bold":true},{"text":", identifies a "},{"text":"trend","bold":true},{"text":", predicts this year's percentage, then sets how much each person should pay."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example: 2.0%, 2.2%, 2.4% in the last three years. The rise is 0.2 percentage points a year, so this year = 2.4% + 0.2% = "},{"text":"2.6%","bold":true},{"text":"."}]},{"text":[{"text":"If the average claim is ₦500,000, the expected claim cost per driver = 0.026 × ₦500,000 = "},{"text":"₦13,000","bold":true},{"text":" (before expenses and profit)."}]}]}]},{"text":[{"text":"Pricing versus reserving:","bold":true},{"text":" deciding what to charge new motor customers next year is "},{"text":"pricing","bold":true},{"text":"; estimating what to hold now for claims on policies already sold is "},{"text":"reserving","bold":true},{"text":"."}]},{"text":[{"text":"Deterministic versus stochastic:","bold":true},{"text":" one fixed 10% interest assumption giving one answer is deterministic; 10,000 random simulations giving a distribution of profits is stochastic."}]}]}]},{"number":"1.5","title":"Where actuaries work, skills, and how they differ from others","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Typical areas of actuarial work:","bold":true},{"text":" insurance (general, health, life); finance (banking, corporate, investment, pensions); data science and analytics; technology; enterprise risk; resource and environment (climate change)."}]},{"text":[{"text":"8 specialisations:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Health and Care"}]},{"text":[{"text":"Life Insurance"}]},{"text":[{"text":"Pensions"}]},{"text":[{"text":"Investment and Finance"}]},{"text":[{"text":"Financial Derivatives"}]},{"text":[{"text":"General Insurance: Reserving"}]},{"text":[{"text":"General Insurance: Pricing"}]},{"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 5, $study_guide$text":[{"text":"Enterprise Risk Management"}]}]}]},{"text":[{"text":"Most common industries:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Insurance:","bold":true},{"text":" property (home) and casualty (auto); life and annuities."}]},{"text":[{"text":"Employee benefits:","bold":true},{"text":" retirement benefits, health benefits, social security."}]},{"text":[{"text":"Financial services:","bold":true},{"text":" banks, investing, risk management, mergers and acquisitions."}]}]}]},{"text":[{"text":"Actuaries are largely employed by "},{"text":"insurance companies and consulting firms","bold":true},{"text":", in "},{"text":"4 areas","bold":true},{"text":": life, annuities and mutual funds; health; pensions; property and casualty."}]},{"text":[{"text":"Skills needed:","bold":true},{"text":" mathematical and analytical skills; project management and problem-solving skills; excellent "},{"text":"communication","bold":true},{"text":" skills (oral and written); strong business sense and commercial awareness; "},{"text":"self-motivation","bold":true},{"text":"; ambition and ability to work in a team. Also: business acumen, computer skills, work ethic, creativity, independence, collaboration."}]},{"text":[{"text":"Besides mathematics, "},{"text":"self-motivation and good communication skills","bold":true},{"text":" are equally important."}]}]},{"type":"table","header":[[],[{"text":"Actuary"}],[{"text":"Accountant"}],[{"text":"CFA"}]],"rows":[[[{"text":"Business focus"}],[{"text":"Financial impact of events that "},{"text":"may or may not occur in the future","bold":true}],[{"text":"Financial impact of events that "},{"text":"have already happened","bold":true}],[{"text":"Analyse financial reports and investments"}]],[[{"text":"How"}],[{"text":"Uses large amounts of data to calculate the probability and impact of future events and what to do"}],[{"text":"Works with "},{"text":"known","bold":true},{"text":" numbers; creates or audits balance sheets and income statements"}],[{"text":"Uses analysis to recommend investments"}]],[[{"text":"Assets and liabilities"}],[{"text":"Both","bold":true},{"text":", specially trained in complicated "},{"text":"liabilities","bold":true}],[{"text":"Reports on both"}],[{"text":"Geared towards "},{"text":"assets","bold":true}]],[[{"text":"Product focus"}],[{"text":"Understands products and how they make money"}],[{"text":"Reports cost, revenue and profit of a product"}],[{"text":"Which products or companies to invest in"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuary vs statistician:","bold":true},{"text":" a statistician collects, analyses and interprets data in any field. An actuary uses statistics and probability "},{"text":"together with financial mathematics and business knowledge","bold":true},{"text":" to put a "},{"text":"money value","bold":true},{"text":" on future risk, mainly in insurance, pensions and finance."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Life:","bold":true},{"text":" term and permanent death-benefit products. "},{"text":"Annuities:","bold":true},{"text":" a lump sum or payments now for periodic payments starting immediately or later. "},{"text":"Mutual fund:","bold":true},{"text":" pools investors' assets to buy securities for a common goal."}]},{"text":[{"text":"Health:","bold":true},{"text":" products for individuals, families and sole proprietors, and plans for employers by size: small group 2 to 50 employees, middle market 51 to 3,000, national accounts 3,001 or more."}]},{"text":[{"text":"Pensions","bold":true},{"text":" give steady income, usually a guaranteed annuity, to retired or disabled employees. "},{"text":"Defined benefit:","bold":true},{"text":" based on pay, years of service, retirement age and other factors. "},{"text":"Defined contribution:","bold":true},{"text":" the employee defers part of salary into the plan and "},{"text":"bears the investment risk","bold":true},{"text":". Nigeria's Contributory Pension Scheme, regulated by "},{"text":"PenCom","bold":true},{"text":", is a defined contribution scheme."}]},{"text":[{"text":"Property and casualty:","bold":true},{"text":" business, personal (auto, homeowners), and financial, professional and international insurance."}]},{"text":[{"text":"Typical projects:","bold":true},{"text":" pricing life products (impact of AIDS on mortality tables); costing motor or home cover in an area (impact of global warming); setting HMO premium rates; pricing increased retirement benefits. In Nigeria, insurers are supervised by "},{"text":"NAICOM","bold":true},{"text":"."}]},{"text":[{"text":"Why self-motivation:","bold":true},{"text":" trainees must "},{"text":"pass professional exams while working full time","bold":true},{"text":"."}]},{"text":[{"text":"Communication in action:","bold":true},{"text":" explaining to a non-mathematical board why premiums must rise."}]},{"text":[{"text":"Applying the table:","bold":true},{"text":" setting aside money today for 30 years of pension promises that depend on how long workers live is an "},{"text":"actuary's","bold":true},{"text":" job. All three professions are prestigious and should work together."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial science evaluates risks and maintains the economic stability of insurance and financial organisations."}]},{"text":[{"text":"An actuary applies mathematical approaches to anticipate, measure and manage risk; Latin actuarius."}]},{"text":[{"text":"Risk = possibility of failing to meet objectives, defined in context; uncertainty = unmeasurable risk."}]},{"text":[{"text":"Actuarial risk variables: occurrence, timing, severity. Contingency = an event that may or may not occur."}]},{"text":[{"text":"Probability is from 0 to 1; expected claim = probability × average claim; large, similar, independent pools reduce variability."}]},{"text":[{"text":"Model: input, processin$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 6, $study_guide$g, output; phases specification, implementation, production; control cycle: define, design, monitor."}]},{"text":[{"text":"Pricing sets future premiums; reserving holds money for claims on policies already sold."}]},{"text":[{"text":"Actuaries look forward and specialise in liabilities; accountants look back; CFAs focus on assets."}]}]}],"theory":{"itemId":"1871811f-78c9-57e1-980e-e0e29fb463ab","question":[{"type":"paragraph","text":[{"text":"An insurer covers 20,000 similar okada riders in Lagos. Past experience shows 1.5% of riders make a claim each year, with an average claim of ₦250,000. Ignoring expenses and profit, find (a) the expected claim cost per rider and (b) the total expected claims. (c) Why is this prediction reliable?"}]}]},"practice":[{"topic":"Nature of Actuarial Science and the Actuary","named":false}]}},{"kind":"note","itemId":"2b31ed30-4ca0-5a79-b2d8-7db48adcbd26","sourceKey":"guide-topic:2","position":2,"payload":{"title":"History and Professional Structure of Actuarial Science","body":"The people, works and dates that built actuarial science (1654 to 1825); the Equitable Society and the first use of the title \"actuary\"; the world's actuarial bodies and when they began; the Nigerian bodies and what each does; the student, associate and fellow grades and the IFoA, SOA and CAS exam pathways; professional standards and ethics; career outlook, supply and demand.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The people, works and dates that built actuarial science (1654 to 1825); the Equitable Society and the first use of the title \"actuary\"; the world's actuarial bodies and when they began; the Nigerian bodies and what each does; the student, associate and fellow grades and the IFoA, SOA and CAS exam pathways; professional standards and ethics; career outlook, supply and demand."}],"lessons":[{"number":"2.1","title":"Probability and the first mortality tables","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"1654, Blaise Pascal and Pierre de Fermat:","bold":true},{"text":" letters on the gambler's \"problem of points\". Treated as the start of "},{"text":"modern probability theory","bold":true},{"text":"."}]},{"text":[{"text":"1662, John Graunt:","bold":true},{"text":" a London draper (cloth tradesman). Published "},{"text":"Natural and Political Observations ... upon the Bills of Mortality","italic":true},{"text":", based on the "},{"text":"weekly London Bills of Mortality","bold":true},{"text":". Showed deaths follow predictable patterns in a population. Main contribution: the "},{"text":"first attempt at a life table","bold":true},{"text":" from death records."}]},{"text":[{"text":"1693, Edmond Halley:","bold":true},{"text":" the astronomer famous for predicting the return of the comet named after him. Built a life table from the "},{"text":"parish records of Breslau","bold":true},{"text":" and showed how to "},{"text":"price a life annuity","bold":true},{"text":" from it. Practical use: life annuities sold by the British government should be priced "},{"text":"according to the buyer's age","bold":true},{"text":"."}]},{"text":[{"text":"1713, Jacob Bernoulli:","bold":true},{"text":" "},{"text":"Ars Conjectandi","italic":true},{"text":", published after his death. Contains an early version of the "},{"text":"law of large numbers","bold":true},{"text":"."}]},{"text":[{"text":"1725, Abraham de Moivre:","bold":true},{"text":" "},{"text":"Annuities upon Lives","italic":true},{"text":" (London). Methods for valuing annuities on one or more lives, using a "},{"text":"postulated uniform rate of mortality","bold":true},{"text":" together with a "},{"text":"constant rate of interest","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Law of large numbers / statistical regularity:","bold":true},{"text":" if similar independent trials are repeated under the same conditions, the proportion of times an event happens settles down (stabilises) as the number of trials grows. Pooling many similar risks makes the insurer's results predictable."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Do not swap the cities: "},{"text":"Graunt = London","bold":true},{"text":" (Bills of Mortality); "},{"text":"Halley = Breslau","bold":true},{"text":". Northampton belongs to Richard Price (Lesson 2.2); Equitable records belong to neither."}]},{"text":[{"text":"Halley's table showed that a young buyer of a life annuity should pay more than an old buyer, because the young buyer is expected to collect payments for longer. A flat price for all ages is wrong."}]},{"text":[{"text":"Law of large numbers in ₦ terms: a Lagos motor insurer with only 200 policies may see 4 accidents one year (2%) and 14 the next (7%). With 50,000 similar policies the yearly rate stays close to 4%, about 2,000 accidents. The insurer can then set a premium with confidence. This is "},{"text":"statistical regularity","bold":true},{"text":", not adverse selection or the time value of money."}]}]}]},{"number":"2.2","title":"The birth of the profession, 1750s to 1825","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"James Dodson","bold":true},{"text":" (died "},{"text":"1757","bold":true},{"text":"): pioneered the "},{"text":"level premium system","bold":true},{"text":" for long-term life assurance. His work led to the founding of the Equitable."}]},{"text":[{"text":"1762, the Society for Equitable Assurances on Lives and Survivorships","bold":true},{"text":" (the "},{"text":"Equitable","bold":true},{"text":", London): the first life office to charge "},{"text":"scientifically calculated premiums","bold":true},{"text":" on long-term policies."}]},{"text":[{"text":"Edward Rowe Mores","bold":true},{"text":", a founder of the Equitable, specified around 1762 that its chief official be called the "},{"text":"actuary","bold":true},{"text":": the first use of the title for a business position. Before then, an actuary (Latin "},{"text":"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 7, $study_guide$actuarius","italic":true},{"text":") was a "},{"text":"clerk who kept the records of a court or senate","bold":true},{"text":"."}]},{"text":[{"text":"William Morgan:","bold":true},{"text":" appointed actuary of the Equitable in "},{"text":"1775","bold":true},{"text":", held the post until "},{"text":"1830","bold":true},{"text":"; often called the "},{"text":"father of the actuarial profession","bold":true},{"text":"."}]},{"text":[{"text":"Richard Price:","bold":true},{"text":" "},{"text":"Observations on Reversionary Payments","italic":true},{"text":" ("},{"text":"1771","bold":true},{"text":"); compiled the "},{"text":"Northampton mortality table","bold":true},{"text":", a British standard for about a century. Weakness: it "},{"text":"overstated mortality","bold":true},{"text":", so "},{"text":"annuities priced on it were sold too cheaply","bold":true},{"text":" (and life cover was overpriced)."}]},{"text":[{"text":"1825, Benjamin Gompertz:","bold":true},{"text":" law of mortality based on the idea that a person's "},{"text":"resistance to death declines","bold":true},{"text":" with age, so the force of mortality rises geometrically: μ_x = B × c^x (B > 0, c > 1)."}]}]},{"type":"table","header":[[{"text":"Premium type"}],[{"text":"What it is"}]],"rows":[[[{"text":"Level premium","bold":true}],[{"text":"The same premium every year for the policy's life; early years overpay, later years underpay"}]],[[{"text":"Natural (yearly risk) premium","bold":true}],[{"text":"Each year's premium matches that year's risk, so it rises with age"}]],[[{"text":"Single premium","bold":true}],[{"text":"One payment at the start covers the whole policy"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Level premium example:","bold":true},{"text":" Bola, aged 30, pays ₦60,000 every year on a whole life policy, and still pays ₦60,000 at 60 although her death risk is now far higher. This is a "},{"text":"level premium","bold":true},{"text":". Her early overpayments build a reserve that meets the shortfall in later years."}]},{"text":[{"text":"Trap: "},{"text":"Gompertz is not linked with the level premium","bold":true},{"text":"; that is Dodson. Gompertz = 1825 law of mortality."}]},{"text":[{"text":"Trap: Mores named the post; "},{"text":"Morgan held it","bold":true},{"text":" for 55 years. Price was Morgan's uncle and adviser."}]}]},{"type":"paragraph","text":[{"text":"Timeline to memorise:","bold":true},{"text":" 1654 Pascal and Fermat · 1662 Graunt · 1693 Halley · 1713 Bernoulli · 1725 de Moivre · 1757 Dodson dies · 1762 Equitable and \"actuary\" · 1771 Price · 1775 to 1830 Morgan · 1825 Gompertz · 1848 Institute of Actuaries."}]}]},{"number":"2.3","title":"Actuarial bodies around the world","mustKnow":[{"type":"table","header":[[{"text":"Body"}],[{"text":"Key facts"}]],"rows":[[[{"text":"Institute of Actuaries","bold":true}],[{"text":"Founded "},{"text":"1848","bold":true},{"text":", London"}]],[[{"text":"Faculty of Actuaries","bold":true}],[{"text":"Founded "},{"text":"1856","bold":true},{"text":", Scotland (Edinburgh); Royal Charter "},{"text":"1868","bold":true},{"text":", the "},{"text":"first actuarial body granted one","bold":true}]],[[{"text":"Institute and Faculty of Actuaries (IFoA)","bold":true}],[{"text":"The two merged on "},{"text":"1 August 2010","bold":true},{"text":"; offices in London, Oxford, Edinburgh, Beijing, Malaysia and Singapore"}]],[[{"text":"Society of Actuaries (SOA)","bold":true}],[{"text":"Formed "},{"text":"1949","bold":true},{"text":" by merging the "},{"text":"Actuarial Society of America","bold":true},{"text":" (1889) and the "},{"text":"American Institute of Actuaries","bold":true},{"text":" (1909); Chicago, Illinois area"}]],[[{"text":"Casualty Actuarial Society (CAS)","bold":true}],[{"text":"Founded "},{"text":"November 1914","bold":true},{"text":" as the "},{"text":"Casualty Actuarial and Statistical Society of America","bold":true},{"text":"; present name "},{"text":"1921","bold":true},{"text":"; Arlington, Virginia (Washington, DC area). Began with "},{"text":"workers' compensation","bold":true},{"text":" insurance"}]],[[{"text":"International Actuarial Association (IAA)","bold":true}],[{"text":"Origin: committee of "},{"text":"1895","bold":true},{"text":", when the first "},{"text":"International Congress of Actuaries","bold":true},{"text":" met in "},{"text":"Brussels","bold":true},{"text":". Restructured in "},{"text":"1998","bold":true},{"text":" at the Congress in "},{"text":"Birmingham","bold":true},{"text":": its full members are "},{"text":"national actuarial associations","bold":true},{"text":" (an association of associations)"}]],[[{"text":"Actuarial Society of South Africa (ASSA)","bold":true}],[{"text":"Cape Town"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Letters: "},{"text":"FIA","bold":true},{"text":" / "},{"text":"FFA","bold":true},{"text":" = Fellow of the Institute / "},{"text":"Fellow of the Faculty of Actuaries","bold":true},{"text":"; "},{"text":"AIA","bold":true},{"text":" = Associate of the Institute. "},{"text":"ASA / FSA","bold":true},{"text":" = SOA; "},{"text":"ACAS / FCAS","bold":true},{"text":" = CAS."}]},{"text":[{"text":"The IAA's "},{"text":"International Standards of Actuarial Practice (ISAPs)","bold":true},{"text":" are "},{"text":"model standards","bold":true},{"text":": member associations are encouraged to align their own standards with them. They are not binding world rules."}]}]},{"type":"paragraph","text":[{"text":"United States professional bodies","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"American Academy of Actuaries","bold":true},{"text":" (1965): its "},{"text":"MAAA","bold":true},{"text":" designation must be held to "},{"text":"sign statements of actuarial opinion","bold":true},{"text":" in the US."}]},{"text":[{"text":"Actuarial Standards Board (ASB):","bold":true},{"text":" promulgates the "},{"text":"Actuarial Standards of Practice ($study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 8, $study_guide$ASOPs)","bold":true},{"text":", which say what an actuary should "},{"text":"consider, document and disclose","bold":true},{"text":" on an assignment."}]},{"text":[{"text":"Actuarial Board for Counseling and Discipline (ABCD):","bold":true},{"text":" reviews complaints that an actuary breached the code of conduct and can recommend discipline."}]}]},{"type":"paragraph","text":[{"text":"Practice areas by body","bold":true}]},{"type":"table","header":[[{"text":"Area"}],[{"text":"IFoA"}],[{"text":"SOA"}],[{"text":"CAS"}],[{"text":"ASSA"}]],"rows":[[[{"text":"Life"}],[{"text":"Yes"}],[{"text":"Yes"}],[{"text":"No"}],[{"text":"Yes"}]],[[{"text":"Pensions/retirement"}],[{"text":"Yes"}],[{"text":"Yes"}],[{"text":"No"}],[{"text":"Yes"}]],[[{"text":"Health"}],[{"text":"Yes"}],[{"text":"Yes"}],[{"text":"No"}],[{"text":"Yes"}]],[[{"text":"General insurance (P&C)"}],[{"text":"Yes"}],[{"text":"No"}],[{"text":"Yes"}],[{"text":"Yes"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"CAS = property and casualty only","bold":true},{"text":": motor (auto) pricing, liability ratemaking and property reserving are CAS work; "},{"text":"life assurance and annuities are not","bold":true},{"text":"."}]},{"text":[{"text":"Chinedu, a general insurance actuary in Lagos, completing CAS Associate requirements writes "},{"text":"ACAS","bold":true},{"text":" (not ASA, which is SOA, and not FCAS, which is Fellow)."}]},{"text":[{"text":"Year traps: 1848 Institute; 1856 Faculty; 1868 Faculty's charter; 1889 Actuarial Society of America; 1762 Equitable."}]},{"text":[{"text":"When these bodies were founded in the mid-19th century, one main purpose besides supporting actuaries was "},{"text":"protecting the public","bold":true},{"text":" by ensuring members' competence and ethical standards. They never set every insurer's premiums, collected taxes or sold policies."}]},{"text":[{"text":"All bodies' syllabuses cover financial mathematics, probability, statistics, accounting, corporate finance, loss and mortality models, reserving, data ethics and model validation. Banking, ERM and microinsurance are notable exclusions from the practice areas above."}]}]}]},{"number":"2.4","title":"The profession and regulators in Nigeria","mustKnow":[{"type":"table","header":[[{"text":"Body"}],[{"text":"Role"}]],"rows":[[[{"text":"Nigerian Actuarial Society (NAS)","bold":true}],[{"text":"Professional body for actuaries","bold":true},{"text":" in Nigeria"}]],[[{"text":"National Insurance Commission (NAICOM)","bold":true}],[{"text":"Government agency established under the "},{"text":"National Insurance Commission Act 1997","bold":true},{"text":"; "},{"text":"regulates and supervises insurers","bold":true}]],[[{"text":"National Pension Commission (PenCom)","bold":true}],[{"text":"Established by the "},{"text":"Pension Reform Act 2004","bold":true},{"text":"; "},{"text":"regulates and supervises pensions","bold":true}]],[[{"text":"Chartered Insurance Institute of Nigeria (CIIN)","bold":true}],[{"text":"Professional body for insurance practitioners (not for actuaries)"}]],[[{"text":"Securities and Exchange Commission (SEC)","bold":true}],[{"text":"Regulates the capital market (not insurance)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"January 2024:","bold":true},{"text":" the University of Lagos MSc Actuarial Science programme was accredited by the "},{"text":"IFoA","bold":true},{"text":", earning its graduates exam exemptions."}]}]},{"type":"paragraph","text":[{"text":"Current landscape in Nigeria (2022 figures)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Supply:","bold":true},{"text":" 19 Fellows, 8 Associates, 70+ students; 5 universities, including UNILAG."}]},{"text":[{"text":"Demand:","bold":true},{"text":" 56 insurance companies, life and non-life (limited in pensions); requirement soon to keep an actuarial function in-house; IFRS 17 and innovations."}]},{"text":[{"text":"Public policy and regulation:","bold":true},{"text":" 3 actuarial staff within NAICOM but no qualified actuaries; no clarity on whether an appointed actuary must be an associate or a fellow; "},{"text":"no local actuarial (mortality) tables","bold":true},{"text":"; plans for risk-based capital requirements and IFRS 17."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory hook: "},{"text":"N","bold":true},{"text":"AICOM = i"},{"text":"N","bold":true},{"text":"surance regulator; "},{"text":"P","bold":true},{"text":"enCom = "},{"text":"P","bold":true},{"text":"ensions regulator; NAS = the actuaries' own society. Exams love swapping these three."}]},{"text":[{"text":"The figures show demand far ahead of supply: 56 insurers but only 19 Fellows in the whole country. That gap is the career opportunity for a UNILAG actuarial student."}]}]}]},{"number":"2.5","title":"Professional structure and how to qualify","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Grades:","bold":true},{"text":" "},{"text":"Student → Associate → Fellow","bold":true},{"text":"."}]},{"text":[{"text":"You qualify by passing a "},{"text":"series of professional exams, usually while working","bold":true},{"text":" (\"earn while you learn\"). Exams are held several times a year. A degree alone does not qualify you."}]},{"text":[{"text":"SOA/CAS:","bold":true},{"text":" "},{"text":"Associate (ASA, ACAS)","bold":true},{"text":" and "},{"text":"Fellow (FSA, FCAS)","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"ASA:","bold":true},{"text":" has shown knowledge of the fundamental concepts and techniques for modelling and managing risk through required exams and learning modules, and completed a professionalism course."}]},{"text":[{"text":"FSA:","bold":true},{"text":" has shown knowledge in "},{"text":"all major practice areas","bold":true},{"text":", with "},{"text":"further concentration in one or more","bold":true},{"text":" of$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 9, $study_guide$ them, plus further professionalism education."}]}]}]},{"text":[{"text":"SOA/CAS joint preliminary exams:","bold":true},{"text":" "},{"text":"P/1","bold":true},{"text":" Probability; "},{"text":"FM/2","bold":true},{"text":" Financial Mathematics; "},{"text":"MFE/3F","bold":true},{"text":" Financial Economics; "},{"text":"C/4","bold":true},{"text":" Actuarial Models. Then SOA's "},{"text":"MLC","bold":true},{"text":" (Life Contingencies) or CAS's "},{"text":"3L","bold":true},{"text":" (Life Contingencies and Statistics)."}]},{"text":[{"text":"SOA upper-level areas:","bold":true},{"text":" Retirement Benefits; Group and Health; Individual Life and Annuities; Investments. "},{"text":"CAS:","bold":true},{"text":" P&C insurance/pricing; reserving; accounting/annual statement; advanced financial management; advanced pricing."}]}]},{"type":"paragraph","text":[{"text":"IFoA pathway","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Core Principles (7):","bold":true},{"text":" CS1, CS2 Actuarial Statistics; CM1, CM2 Actuarial Mathematics; CB1 Business Finance; CB2 Business Economics; CB3 Business Management (Professional Skills Stage 1 needed before CB3)."}]},{"text":[{"text":"Core Practices (3):","bold":true},{"text":" "},{"text":"CP1 Actuarial Practice","bold":true},{"text":", CP2 Modelling Practice, CP3 Communication Practice."}]},{"text":[{"text":"Associate","bold":true},{"text":" = Core Principles + Core Practices + "},{"text":"2 years of PPD","bold":true},{"text":" (Personal and Professional Development) + "},{"text":"Professional Skills Stages 1 and 2","bold":true},{"text":"."}]},{"text":[{"text":"Specialist Principles (choose 2 of 8):","bold":true},{"text":" SP1 Health and Care, SP2 Life Insurance, SP4 Pensions and Other Benefits, SP5 Investment and Finance, SP6 Financial Derivatives, SP7 General Insurance Reserving and Capital Modelling, SP8 General Insurance Pricing, SP9 Enterprise Risk Management."}]},{"text":[{"text":"Specialist Advanced (choose 1, the final exam):","bold":true},{"text":" SA1 Health and Care, SA2 Life Insurance, SA3 General Insurance, SA4 Pensions and Other Benefits, SA7 Investment and Finance."}]},{"text":[{"text":"Fellow","bold":true},{"text":" = 2 SP + 1 SA + "},{"text":"3 years of PPD in total","bold":true},{"text":" (one more year after Associate)."}]}]},{"type":"paragraph","text":[{"text":"Ethics and standards","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Code of Professional Conduct:","bold":true},{"text":" sets out what it means for an actuary to act as a professional; responsibilities to "},{"text":"the public","bold":true},{"text":", to "},{"text":"clients and employers","bold":true},{"text":", and to "},{"text":"the actuarial profession","bold":true},{"text":". It brings accountability, responsibility and trust."}]},{"text":[{"text":"Professionalism:","bold":true},{"text":" professional status, methods, character or standards; adherence to the Code."}]},{"text":[{"text":"Continuing professional development (CPD):","bold":true},{"text":" qualified members keep learning and record it each year to stay competent."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: competing firms are "},{"text":"not","bold":true},{"text":" among the groups the Code protects."}]},{"text":[{"text":"Trap: \"Associate\" needs all Core exams but "},{"text":"no","bold":true},{"text":" Specialist exams; \"Fellow\" adds 2 SP, 1 SA and the third PPD year. CP1 is Core Practices; CM1 and CB2 are Core Principles; SP2 is Specialist."}]},{"text":[{"text":"Tax Auditing is not","bold":true},{"text":" an IFoA Specialist Principles subject."}]},{"text":[{"text":"Skills needed:","bold":true},{"text":" mathematical and analytical skill, project management and problem solving, communication (oral and written), business sense, self-motivation (you pass exams while working), teamwork, creativity and independence."}]}]}]},{"number":"2.6","title":"Specialisations and career outlook","mustKnow":[{"type":"paragraph","text":[{"text":"8 specialisations:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Health and Care"}]},{"text":[{"text":"Life Insurance"}]},{"text":[{"text":"Pensions"}]},{"text":[{"text":"Investment and Finance"}]},{"text":[{"text":"Financial Derivatives"}]},{"text":[{"text":"General Insurance: Reserving"}]},{"text":[{"text":"General Insurance: Pricing"}]},{"text":[{"text":"Enterprise Risk Management"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Career outlook:","bold":true},{"text":" the "},{"text":"2002 Jobs Rated Almanac","bold":true},{"text":" ranked actuary "},{"text":"number 2","bold":true},{"text":" in America (number 1 biologist, 3 financial planner, 5 accountant, 9 statistician)."}]},{"text":[{"text":"Pay:","bold":true},{"text":" US starting salaries of about 46,000 to 65,000 US dollars (one exam passed, 0 to 0.5 years' experience; base pay only, 2009 survey), rising with merit, with "},{"text":"each exam passed","bold":true},{"text":" and on reaching each designation."}]}]},{"type":"paragraph","text":[{"text":"10 reasons to become an actuary:","bold":true},{"text":" (1) competitive salary and benefits; (2) suits the self-motivated with strong maths and communication; (3) a choice of job offers; (4) earn while you learn; (5) job security through economic cycles; (6) skills transferable across industries; (7) early advancement is largely exam-based, so you control it; (8) dynamic, challenging work; (9) a professional title without being a doctor, lawyer or accountant; (10) continual learning. Also: international opportunities and globally recognised qualifications."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pensions example:","bold":true},{"text":" Ngozi, at an Abuja consulting firm, projects staff salaries and retirement ages and estimates how much to set aside today for future retirement benefits. Tha$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 10, $study_guide$t is "},{"text":"pensions","bold":true},{"text":" work. If the fund's benefits are ₦500 million due in 10 years and the fund can earn 10% a year, the amount to set aside now is ₦500,000,000 × (1.10)^-10 = ₦192,771,645 (to the nearest naira)."}]},{"text":[{"text":"Health and care prices medical cover (for example HMO premiums); financial derivatives values options; general insurance pricing sets motor and home premiums."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"1654 Pascal and Fermat (probability); 1662 Graunt, London Bills (first life table attempt); 1693 Halley, Breslau (annuity price by age)."}]},{"text":[{"text":"1713 Bernoulli (law of large numbers); 1725 de Moivre (uniform mortality plus constant interest)."}]},{"text":[{"text":"Dodson (died 1757) = level premium; 1762 Equitable = first scientific premiums; Mores named the \"actuary\" (once a court clerk); Morgan, actuary 1775 to 1830, father of the profession."}]},{"text":[{"text":"Price's Northampton table overstated mortality, so annuities were too cheap; Gompertz 1825 law of mortality."}]},{"text":[{"text":"Institute 1848; Faculty 1856, charter 1868; IFoA 1 August 2010; SOA 1949; CAS 1914 (named 1921); IAA from 1895 Brussels, association of associations since 1998."}]},{"text":[{"text":"NAS = actuaries; NAICOM (1997 Act) = insurers; PenCom (Pension Reform Act 2004) = pensions."}]},{"text":[{"text":"Student → Associate → Fellow, by exams while working; IFoA Associate needs 2 years PPD, Fellow 3."}]},{"text":[{"text":"Code: duties to the public, clients and employers, and the profession."}]}]}],"theory":{"itemId":"09606d73-a9a7-537f-8892-586f175d7f31","question":[{"type":"paragraph","text":[{"text":"Arrange in time order, earliest first: founding of the Institute of Actuaries; Halley's Breslau table; Graunt's observations; founding of the Equitable Society. Give the year of each."}]}]},"practice":[{"topic":"History and Professional Structure of Actuarial Science","named":false}]}},{"kind":"note","itemId":"0cd5f33d-3cbd-586f-8811-b995c1dbb3b4","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Actuarial Symbols, Notations and Life Tables","body":"The general principles of the international actuarial notation (the four spaces around a symbol); the interest symbols i, i^(m), d, d^(m), v, δ and how they link; the mortality, annuity and assurance letters and their marks; the life table columns l_x, d_x, q_x, p_x and their properties; multi-year probabilities _np_x, _nq_x, m|q_x; survival functions; expectation of life; select and ultimate tables.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"The general principles of the international actuarial notation (the four spaces around a symbol); the interest symbols i, i^(m), d, d^(m), v, δ and how they link; the mortality, annuity and assurance letters and their marks; the life table columns l_x, d_x, q_x, p_x and their properties; multi-year probabilities _np_x, _nq_x, m|q_x; survival functions; expectation of life; select and ultimate tables."}],"lessons":[{"number":"3.1","title":"How the international actuarial notation is built","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Origin:","bold":true},{"text":" based on George King's \"Key to the Notation\"; set out in an explanatory statement adopted "},{"text":"unanimously","bold":true},{"text":" at the "},{"text":"Second International Actuarial Congress, London, May 1898","bold":true},{"text":". Dr Sprague's rearranged statement followed at the "},{"text":"Third Congress, Paris, 1900","bold":true},{"text":" (no real change to the symbols beyond two slight additions). The "},{"text":"Eleventh Congress, Paris, 1937","bold":true},{"text":" appointed a committee (met Brussels 1938 and 1939); the planned 1940 Lucerne adoption was stopped by the war, so the "},{"text":"Institute of Actuaries and the Faculty of Actuaries","bold":true},{"text":" adopted the agreed changes in "},{"text":"1949","bold":true},{"text":", effective from the May 1950 examinations."}]},{"text":[{"text":"General principle:","bold":true},{"text":" each principal (fundamental) letter carries signs in four positions:"}]}]},{"type":"table","header":[[{"text":"Position"}],[{"text":"Reserved for"}],[{"text":"Example"}]],"rows":[[[{"text":"Lower "},{"text":"left","bold":true}],[{"text":"duration","bold":true},{"text":" of the operation and its "},{"text":"position in time","bold":true}],[{"text":"n in _np_x; m| in m|a_x (deferment)"}]],[[{"text":"Lower "},{"text":"right","bold":true}],[{"text":"ages","bold":true},{"text":" of the lives and the "},{"text":"order of succession","bold":true},{"text":" of events"}],[{"text":"x in q_x, l_x, a_x"}]],[[{"text":"Upper "},{"text":"right","bold":true}],[{"text":"periodicity","bold":true},{"text":" (frequency) of events"}],[{"text":"(m) in i^(m), a^(m)_x"}]],[[{"text":"Upper "},{"text":"left","bold":true}],[{"text":"free","bold":true},{"text":": signs for any other notion"}],[]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Two conventions:","bold":true},{"text":" (x) in brackets = "},{"text":"a person aged x","bold":true},{"text":". A number in a right angle, n| or 15|, = a "},{"text":"term-certain","bold":true},{"text":" of n years."}]},{"text":[{"text":"Deferment:","bold":true},{"text":" m| in the lower left means \"deferred m years\", e.g. m|a_x = life annuity on (x) deferred m years; m|q_x = probability (x) survives m years then dies in the next year."}]}]},{"type":"paragraph","text":[{"text":"The 1949 changes","bold":true},{"text":" (know them, and know what was "},{"text":"not","bold":true},{"text":" adopted):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"i^(m) replaced j(m) for the nominal rate of interest convertible m times a year (local use of j(m) still allowed)."}]},{"text":[{"text":"ä (trema) adopted for the annuity-due (first payment at once); this allowed the new symbol s̈_n| for the accumulated amount of an a$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 11, $study_guide$nnuity-due at the end of the term."}]},{"text":[{"text":"Q (probability of dying within more than 1 year) was dropped."}]},{"text":[{"text":"D introduced in compound symbols for "},{"text":"decreasing","bold":true},{"text":" benefits."}]},{"text":[{"text":"Old commutation-column definitions abolished."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"U for surrender value was NOT adopted","bold":true},{"text":" as an international symbol (only agreed that U should be chosen if a symbol were needed)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In _5p_30 the 5 (lower left) is a duration and the 30 (lower right) an age; in i^(12) the 12 (upper right) is how often interest is convertible."}]},{"text":[{"text":"Trap: options swap \"lower left\" (duration/time) and \"lower right\" (ages/order). Memory aid: "},{"text":"left = length of time, right = the life","bold":true},{"text":"."}]},{"text":[{"text":"Trap: the 1898 Congress was in "},{"text":"London","bold":true},{"text":"; 1900 and 1937 were in "},{"text":"Paris","bold":true},{"text":"; no Lucerne congress took place in 1940."}]}]}]},{"number":"3.2","title":"Interest symbols and their relationships","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"i:","bold":true},{"text":" the "},{"text":"effective rate of interest","bold":true},{"text":": the total interest earned on 1 in a year, assuming any interest received more often than yearly is reinvested at once on the same terms as the original principal."}]},{"text":[{"text":"i^(m):","bold":true},{"text":" the "},{"text":"nominal rate of interest convertible m times a year","bold":true},{"text":" (m-thly)."}]},{"text":[{"text":"d:","bold":true},{"text":" the "},{"text":"effective rate of discount","bold":true},{"text":": the discount on 1 due a year hence."}]},{"text":[{"text":"d^(m):","bold":true},{"text":" the "},{"text":"nominal rate of discount convertible m times a year","bold":true},{"text":"."}]},{"text":[{"text":"v:","bold":true},{"text":" the "},{"text":"present value of 1 due a year hence","bold":true},{"text":" (discount factor)."}]},{"text":[{"text":"δ (delta):","bold":true},{"text":" the "},{"text":"force of interest","bold":true},{"text":": the instantaneous rate of growth, like a nominal rate compounded continuously; δ = lim i^(m) as m → ∞."}]}]},{"type":"paragraph","text":[{"text":"Relationships (all equivalent at the same rate):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"v = 1/(1 + i) = (1 + i)^-1"}]},{"text":[{"text":"d = i/(1 + i) = iv = 1 - v"}]},{"text":[{"text":"i = d/(1 - d)"}]},{"text":[{"text":"1 + i = (1 + i^(m)/m)^m, so i^(m) = m[(1 + i)^(1/m) - 1]"}]},{"text":[{"text":"1 - d = (1 - d^(m)/m)^m"}]},{"text":[{"text":"1 + i = e^δ, δ = ln(1 + i), v = e^-δ"}]},{"text":[{"text":"Present value of 1 due in n years = v^n; 1 grows to (1 + i)^n."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example at i = 8% (rounded to 5 decimal places):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"v = 1/1.08 = "},{"text":"0.92593","bold":true}]},{"text":[{"text":"d = 0.08/1.08 = "},{"text":"0.07407","bold":true},{"text":" (check: 1 - v = 0.07407, iv = 0.08 × 0.92593 = 0.07407)"}]},{"text":[{"text":"δ = ln 1.08 = "},{"text":"0.07696","bold":true}]},{"text":[{"text":"i^(12) = 12 × (1.08^(1/12) - 1) = "},{"text":"0.07721","bold":true}]},{"text":[{"text":"v^5 = 1.08^-5 = "},{"text":"0.68058","bold":true},{"text":", so ₦1,000,000 due in 5 years is worth ₦680,583.20 now."}]}]},{"type":"paragraph","text":[{"text":"More conversions:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Nominal i^(4) = 10% convertible quarterly: i = (1 + 0.10/4)^4 - 1 = 1.025^4 - 1 = "},{"text":"0.10381","bold":true},{"text":" (10.381%)."}]},{"text":[{"text":"d = 6%: i = 0.06/0.94 = "},{"text":"0.06383","bold":true},{"text":"."}]},{"text":[{"text":"δ = 0.05: v = e^-0.05 = "},{"text":"0.95123","bold":true},{"text":"."}]},{"text":[{"text":"A Lagos bank quoting \"12% per annum convertible monthly\" is quoting "},{"text":"i^(12) = 0.12","bold":true},{"text":", not i = 0.12 and not δ. Its effective rate is higher: 1.01^12 - 1 = 12.683%."}]},{"text":[{"text":"Ordering at any positive rate: d < d^(m) < δ < i^(m) < i. Discount rates are always smaller than the matching interest rates."}]},{"text":[{"text":"Trap: d (interest) is the discount on 1 due a year hence; d_x (life table) is the number dying."}]}]}]},{"number":"3.3","title":"Mortality, annuity and assurance symbols","mustKnow":[{"type":"paragraph","text":[{"text":"Fundamental letters (mortality tables):","bold":true}]},{"type":"table","header":[[{"text":"Letter"}],[{"text":"Meaning"}],[{"text":"Letter"}],[{"text":"Meaning"}]],"rows":[[[{"text":"l"}],[{"text":"number living"}],[{"text":"a"}],[{"text":"present value of an annuity"}]],[[{"text":"d"}],[{"text":"number dying"}],[{"text":"s"}],[{"text":"amount","bold":true},{"text":" (accumulated value) of an annuity"}]],[[{"text":"p"}],[{"text":"probability of living"}],[{"text":"e"}],[{"text":"expectation of life"}]],[[{"text":"q"}],[{"text":"probability of dying"}],[{"text":"A"}],[{"text":"present value of an assurance"}]],[[{"text":"µ (mu)"}],[{"text":"force of mortality"}],[{"text":"E"}],[{"text":"present value of an endowment"}]],[[{"text":"m"}],[{"text":"central death rate"}],[{"text":"P"}],[{"text":"premium per annum (net premium)"}]],[[{"text":"V"}],[{"text":"policy value"}],[{"text":"W"}],[{"text":"paid-up policy"}]]]},{"type":"paragraph","text":[{"text":"Life-table symbols:","bold":true},{"text":" l_x = number who attain age x; d_x = l_x - l_(x+1) = number who die between x and x + 1; p_x = probability (x) lives 1 year; q_x = probability (x) dies within 1 year; µ_x = force of mortality at age x; m_x = central death rate for the year of age x to x + 1; e_x = "},{"text":"curtate","bold":true},{"text":" expectation of life (average after-lifetime) of (x)."}]},{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 12, $study_guide$ype":"paragraph","text":[{"text":"Annuities-certain (term n|):","bold":true}]},{"type":"table","header":[[{"text":"Symbol"}],[{"text":"Meaning"}],[{"text":"Formula"}]],"rows":[[[{"text":"a_n|"}],[{"text":"PV of 1 a year for n years, paid at "},{"text":"end","bold":true},{"text":" of each year (annuity-immediate)"}],[{"text":"(1 - v^n)/i"}]],[[{"text":"ä_n|"}],[{"text":"PV of the same, paid at the "},{"text":"beginning","bold":true},{"text":" of each year (annuity-due)"}],[{"text":"(1 - v^n)/d = (1 + i)a_n| = 1 + a_(n-1)|"}]],[[{"text":"s_n|"}],[{"text":"amount","bold":true},{"text":" (accumulated value at end of term), payments at end of year"}],[{"text":"((1 + i)^n - 1)/i"}]],[[{"text":"s̈_n|"}],[{"text":"amount at end of term of the annuity-due"}],[{"text":"(1 + i)s_n|"}]]]},{"type":"paragraph","text":[{"text":"Life contingency symbols on (x):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A_x:","bold":true},{"text":" whole life assurance (paid at end of year of death)."}]},{"text":[{"text":"A^1_x:n|","bold":true},{"text":" (1 over the x): n-year "},{"text":"term","bold":true},{"text":" assurance; pays only if (x) dies within n years."}]},{"text":[{"text":"A_x:n|:","bold":true},{"text":" n-year "},{"text":"endowment assurance","bold":true},{"text":": pays at end of year of death within n years, or at end of n years if (x) is alive."}]},{"text":[{"text":"_nE_x","bold":true},{"text":" (also A_x:n| with 1 over the n|): pure endowment; pays only if (x) survives n years."}]},{"text":[{"text":"a_x:","bold":true},{"text":" whole life annuity, payments at end of each year while (x) lives."}]},{"text":[{"text":"a_x:n|:","bold":true},{"text":" "},{"text":"temporary","bold":true},{"text":" life annuity on (x) for n years. "},{"text":"ä_x:n|:","bold":true},{"text":" the same as an annuity-due."}]}]},{"type":"paragraph","text":[{"text":"Marks on the principal letter:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Bar","bold":true},{"text":" (ā_x, Ā_x): "},{"text":"continuous","bold":true},{"text":" (momently) annuity, or assurance payable at the "},{"text":"moment of death","bold":true},{"text":"."}]},{"text":[{"text":"Small circle","bold":true},{"text":" (e̊_x): "},{"text":"complete","bold":true},{"text":" rather than curtate."}]},{"text":[{"text":"Diaeresis or trema","bold":true},{"text":" (ä, s̈): "},{"text":"acceleration","bold":true},{"text":" of payments (paid at the beginning)."}]},{"text":[{"text":"Square brackets","bold":true},{"text":" on the age, l_[x]+t: "},{"text":"selection","bold":true},{"text":"; selected at age x, t years ago, now aged x + t. a_[x] = annuity on a life now aged x and select now; a_[x-n]+n = annuity on a life now aged x, selected n years ago at age x - n."}]}]},{"type":"paragraph","text":[{"text":"Several lives in the suffix:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Letters with no mark (a_xyz): "},{"text":"joint lives","bold":true},{"text":"; lasts while "},{"text":"all","bold":true},{"text":" survive."}]},{"text":[{"text":"Colon","bold":true},{"text":" (a_x:n|) separates items to avoid confusion with "},{"text":"decimals","bold":true},{"text":" when numbers are involved."}]},{"text":[{"text":"Vertical bar","bold":true},{"text":" (a_y|x): status after the bar follows the one before; "},{"text":"reversionary annuity","bold":true},{"text":" to (x) after the death of (y)."}]},{"text":[{"text":"Horizontal bar over the suffix:","bold":true},{"text":" last "},{"text":"survivor","bold":true},{"text":". A number r above it = "},{"text":"at least r","bold":true},{"text":" survivors; "},{"text":"[r]","bold":true},{"text":" = "},{"text":"exactly r","bold":true},{"text":"; no number = at least one."}]},{"text":[{"text":"Numerals over or under","bold":true},{"text":" a life give the "},{"text":"order of failure","bold":true},{"text":": A^1_xy (1 over x) pays on death of (x) only if (x) dies "},{"text":"first","bold":true},{"text":"; A^2_xyz (2 over x) pays if (x) dies second."}]}]},{"type":"paragraph","text":[{"text":"Premiums and compound symbols:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"P = net premium; "},{"text":"P'","bold":true},{"text":" = a "},{"text":"valuation premium","bold":true},{"text":" other than the net premium (policy value V'); "},{"text":"P''","bold":true},{"text":" = the "},{"text":"office (commercial) premium","bold":true},{"text":" (paid-up policy W''). P^[m] = m-thly premium continuing to the end of the year of death."}]},{"text":[{"text":"(Ia)","bold":true},{"text":" = annuity starting at 1 and "},{"text":"increasing by 1","bold":true},{"text":" a year; (IA) = increasing assurance; "},{"text":"D","bold":true},{"text":" = decreasing (e.g. starting at n, falling by 1 a year); "},{"text":"v","bold":true},{"text":" in (va) = varying."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"e_x and a_x:","bold":true},{"text":" a_x = Σ v^k × _kp_x, and e_x = Σ _kp_x. So e_x is a_x valued at "},{"text":"i = 0","bold":true},{"text":"; likewise e̊_x is ā_x at i = 0."}]},{"text":[{"text":"Nigerian example:","bold":true},{"text":" a 15-year policy for a 35-year-old paying ₦2,000,000 at the end of the year of death within 15 years, or at the end of 15 years if alive, is an endowment assurance: "},{"text":"A_35:15|","bold":true},{"text":". If it paid only on death within 15 years it would be A^1_35:15|; only on survival, _15E_35."}]},{"text":[{"text":"Annuity example","bold":true},{"text":" at i = 8%, n = 5 (rounded to 4 dp): v^5 = 0.68058; a_5| = (1 - 0.68058)/0.08 = "},{"text":"3.9927","bold":true},{"text":"; ä_5| = 1.08 × 3.9927 = "},{"text":"4.3121","bold":true},{"text":" (check: 1 + a_4| = 1 + 3.3121 = 4.3121); s_5| = (1.08^5 - 1)/0.08 = "},{"text":"5.8666","bold":true},{"text":"; s̈_5| = 1.08 × 5.8666 = "},{"text":"6.3359","bold":true},{"text":". So ₦50,000 at the end of each year for 5 years is worth 50,000 × 3.$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 13, $study_guide$99271 = ₦199,635.50 now; paid at the start of each year, 50,000 × 4.31213 = ₦215,606.34."}]},{"text":[{"text":"Using ä_n| = 1 + a_(n-1)|:","bold":true},{"text":" if a_9| = 7.1078, then ä_10| = 1 + 7.1078 = "},{"text":"8.1078","bold":true},{"text":"."}]},{"text":[{"text":"Trap: s is the "},{"text":"amount","bold":true},{"text":" (accumulated value) of an annuity, never its present value; a is the present value."}]}]}]},{"number":"3.4","title":"The life table and its characteristics","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Mortality:","bold":true},{"text":" the incidence of death in a population, often measured by the probability that a randomly selected individual would die in some period of time."}]},{"text":[{"text":"Life (mortality) table:","bold":true},{"text":" a table showing, for each age x, how many of a starting group are still alive (l_x) and how many die (d_x), with the probabilities q_x and p_x. It is used for "},{"text":"analysing mortality and survival patterns","bold":true},{"text":"."}]},{"text":[{"text":"Radix:","bold":true},{"text":" the starting number l_0 (or l at the youngest age), a convenient round figure such as 100,000 or 1,000."}]},{"text":[{"text":"Limiting age (ω):","bold":true},{"text":" the age beyond which no one survives; l_ω = 0."}]}]},{"type":"paragraph","text":[{"text":"Formulas:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"d_x = l_x - l_(x+1)"}]},{"text":[{"text":"q_x = d_x/l_x"}]},{"text":[{"text":"p_x = l_(x+1)/l_x = 1 - q_x"}]},{"text":[{"text":"p_x + q_x = 1"}]},{"text":[{"text":"l_(x+1) = l_x × p_x = l_x × (1 - q_x); d_x = l_x × q_x"}]},{"text":[{"text":"Expected survivors or deaths in a group = group size × probability."}]}]},{"type":"paragraph","text":[{"text":"Characteristics of a standard life table:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"l_x "},{"text":"decreases","bold":true},{"text":" (never increases) as age rises."}]},{"text":[{"text":"d_x = l_x - l_(x+1) at every age."}]},{"text":[{"text":"p_x + q_x = 1 at every age; both lie between 0 and 1."}]},{"text":[{"text":"The sum of d_x from age x to the end of the table equals l_x (everyone eventually dies)."}]},{"text":[{"text":"It starts from a radix and ends at the limiting age."}]}]},{"type":"paragraph","text":[{"text":"Select and ultimate:","bold":true},{"text":" newly accepted (medically selected) lives die at lower rates than others of the same age. A "},{"text":"select table","bold":true},{"text":" shows mortality by age at selection [x] and duration since selection; after the "},{"text":"select period","bold":true},{"text":" the effect wears off and "},{"text":"ultimate","bold":true},{"text":" rates (depending on attained age only) apply. A table without selection is an aggregate table. "},{"text":"Selection","bold":true},{"text":" is also the process by which an insurer decides whether to accept a risk and which set of probabilities to assign it."}]},{"type":"paragraph","text":[{"text":"Uses:","bold":true},{"text":" pricing life assurance and annuities (premiums), reserves and policy values, pension and social security costs, demographic study of a population."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Construction:","bold":true},{"text":" observe a large group (a national population from census and death registration, or an insurer's own policyholders), count exposed lives and deaths at each age to get crude q_x, smooth them (graduation), then start from the radix and apply l_(x+1) = l_x × (1 - q_x)."}]},{"text":[{"text":"Nigeria:","bold":true},{"text":" a 2022 review of the Nigerian actuarial market noted there are "},{"text":"no local actuarial tables","bold":true},{"text":". Nigerian life insurers (supervised by NAICOM) and pension schemes (supervised by PenCom) therefore base their q_x and l_x on tables built from "},{"text":"other populations","bold":true},{"text":"."}]},{"text":[{"text":"The actuary pricing a one-year term assurance for a 45-year-old needs "},{"text":"q_45","bold":true},{"text":" directly."}]},{"text":[{"text":"Trap: l_x is the "},{"text":"number alive at exact age x","bold":true},{"text":", not a probability and not the number dying."}]}]}]},{"number":"3.5","title":"Worked life table and multi-year probabilities","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"_np_x","bold":true},{"text":" (often printed npx or 3p50): probability (x) survives n years = l_(x+n)/l_x."}]},{"text":[{"text":"_nq_x:","bold":true},{"text":" probability (x) dies within n years = 1 - _np_x = (l_x - l_(x+n))/l_x."}]},{"text":[{"text":"m|q_x:","bold":true},{"text":" (x) survives m years then dies in the next year = d_(x+m)/l_x = (l_(x+m) - l_(x+m+1))/l_x."}]},{"text":[{"text":"m|nq_x:","bold":true},{"text":" (x) survives m years then dies within the next n years = (l_(x+m) - l_(x+m+n))/l_x."}]},{"text":[{"text":"Chain rule:","bold":true},{"text":" _np_x = p_x × p_(x+1) × ... × p_(x+n-1) = (1 - q_x)(1 - q_(x+1))...(1 - q_(x+n-1))."}]},{"text":[{"text":"Deaths between x and x + n = l_x - l_(x+n) = d_x + d_(x+1) + ... + d_(x+n-1)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example","bold":true},{"text":" (probabilities rounded to 5 dp):"}]},{"type":"table","header":[[{"text":"x"}],[{"text":"l_x"}],[{"text":"d_x = l_x - l_(x+1)"}],[{"text":"q_x = d_x/l_x"}],[{"text":"p_x = l_(x+1)/l_x"}]],"rows":[[[{"text":"30"}],[{"text":"95,000"}],[{"text":"190"}],[{"text":"0.00200"}],[{"text":"0.99800"}]],[[{"text":"31"}],[{"text":"94,810"}],[{"text":"200"}],[{"text":"0.00211"}],[{"text":"0.99789"}]],[[{"text":"32"}],[{"text":"94,610"}],[{"text":"215"}],[{"text":"0.00227"}],[{"text":"0.99773"}]],[[{"text":"33"}],[{"text":"94,395"}],[{"text":"235"}],[{"text":"0.00249"}],[{"text":"0.99751"}]],[[{"text":"34"}],[{"text":"94,160"}],[{"text":"260"}],[{"text":"0.00276"}],[{"text":"0.99724"}]],[[{"text":"35"}],[{"text":"93,90$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 14, $study_guide$0"}],[],[],[]]]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"_3p_30 = l_33/l_30 = 94,395/95,000 = "},{"text":"0.99363","bold":true},{"text":"."}]},{"text":[{"text":"_5p_30 = 93,900/95,000 = "},{"text":"0.98842","bold":true},{"text":"; _5q_30 = 1 - 0.98842 = 0.01158. Check: 190 + 200 + 215 + 235 + 260 = 1,100 = 95,000 - 93,900."}]},{"text":[{"text":"_2q_31 = 1 - l_33/l_31 = 1 - 94,395/94,810 = 415/94,810 = "},{"text":"0.00438","bold":true},{"text":"."}]},{"text":[{"text":"2|q_30 = d_32/l_30 = 215/95,000 = "},{"text":"0.00226","bold":true},{"text":"."}]},{"text":[{"text":"1|2q_30 = (l_31 - l_33)/l_30 = (94,810 - 94,395)/95,000 = 415/95,000 = "},{"text":"0.00437","bold":true},{"text":". Note the divisor is l_30, not l_31: that is why it differs from _2q_31."}]},{"text":[{"text":"500 lives aged exactly 30: expected alive at 35 = 500 × 0.988421 = "},{"text":"494.21","bold":true},{"text":", about 494."}]},{"text":[{"text":"A Lagos insurer covers 2,000 lives aged 32, each for ₦1,000,000 for one year: expected deaths = 2,000 × 215/94,610 = "},{"text":"4.54","bold":true},{"text":"; expected claims = 4.54497 × ₦1,000,000 ≈ "},{"text":"₦4,544,974","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Building a table from q_x:","bold":true},{"text":" radix l_50 = 20,000, q_50 = 0.010, q_51 = 0.012, q_52 = 0.015."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"d_50 = 20,000 × 0.010 = 200; l_51 = 19,800."}]},{"text":[{"text":"d_51 = 19,800 × 0.012 = 237.6; l_52 = 19,562.4."}]},{"text":[{"text":"d_52 = 19,562.4 × 0.015 = 293.436; l_53 = "},{"text":"19,268.964","bold":true},{"text":" (19,268.96 to 2 dp)."}]},{"text":[{"text":"_3p_50 = 0.990 × 0.988 × 0.985 = "},{"text":"0.96345","bold":true},{"text":" = 19,268.964/20,000. Check: _3q_50 = 0.03655."}]},{"text":[{"text":"From d_x alone: if l_70 = 5,000 and d_70, d_71, d_72 are given, l_73 = 5,000 - (d_70 + d_71 + d_72); then q_71 = d_71/l_71 with l_71 = 5,000 - d_70."}]},{"text":[{"text":"Trap: _nq_x is "},{"text":"not","bold":true},{"text":" the sum of the q's, and _np_x is "},{"text":"not","bold":true},{"text":" l_(x+n) alone. Always divide by l at the "},{"text":"starting","bold":true},{"text":" age."}]}]}]},{"number":"3.6","title":"Survival functions and expectation of life","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Survival function s(x):","bold":true},{"text":" probability a newborn survives to age x; s(x) = l_x/l_0, s(0) = 1, falls to 0 at the limiting age."}]},{"text":[{"text":"l_x = l_0 × s(x)."}]},{"text":[{"text":"_np_x = s(x + n)/s(x); _nq_x = 1 - s(x + n)/s(x)."}]},{"text":[{"text":"Probability a "},{"text":"newborn","bold":true},{"text":" dies between ages a and b = s(a) - s(b)."}]},{"text":[{"text":"Curtate expectation of life:","bold":true},{"text":" e_x = (l_(x+1) + l_(x+2) + ... )/l_x = Σ _kp_x (k = 1, 2, ...): average number of "},{"text":"complete","bold":true},{"text":" future years lived by (x)."}]},{"text":[{"text":"Complete expectation of life e̊_x:","bold":true},{"text":" average total future lifetime including fractions; approximately e̊_x ≈ e_x + 0.5 (deaths spread evenly over each year)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example:","bold":true},{"text":" s(x) = 1 - x/100, 0 ≤ x ≤ 100."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Newborn survives to 25: s(25) = 1 - 0.25 = "},{"text":"0.75","bold":true},{"text":"."}]},{"text":[{"text":"_25p_40 = s(65)/s(40) = 0.35/0.60 = "},{"text":"0.5833","bold":true},{"text":" (4 dp)."}]},{"text":[{"text":"_30q_40 = 1 - s(70)/s(40) = 1 - 0.30/0.60 = "},{"text":"0.50","bold":true},{"text":"."}]},{"text":[{"text":"Newborn dies between 20 and 50: s(20) - s(50) = 0.80 - 0.50 = "},{"text":"0.30","bold":true},{"text":"."}]},{"text":[{"text":"Radix l_0 = 10,000: l_60 = 10,000 × 0.40 = "},{"text":"4,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Square-root example:","bold":true},{"text":" s(x) = √(1 - x/100). s(19) = √0.81 = 0.9; s(51) = √0.49 = 0.7; a life aged 19 survives to 51 with probability 0.7/0.9 = 7/9 = "},{"text":"0.7778","bold":true},{"text":". The same method works for any s(x), such as (1 - x/100)^2: divide s at the later age by s at the current age."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"a life aged 0 dies between 16 and 43\" uses s(16) - s(43); \"a life aged 16 survives to 43\" uses s(43)/s(16). Watch who the life is now."}]}]},{"type":"paragraph","text":[{"text":"Expectation example:","bold":true},{"text":" l_90 = 500, l_91 = 300, l_92 = 150, l_93 = 60, l_94 = 15, l_95 = 0."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"e_90 = (300 + 150 + 60 + 15)/500 = 525/500 = "},{"text":"1.05","bold":true},{"text":" years."}]},{"text":[{"text":"e_92 = (60 + 15)/150 = "},{"text":"0.50","bold":true},{"text":" years."}]},{"text":[{"text":"e̊_90 ≈ 1.05 + 0.5 = "},{"text":"1.55","bold":true},{"text":" years."}]},{"text":[{"text":"Trap: the sum starts at l_(x+1), "},{"text":"not","bold":true},{"text":" l_x. Including l_x adds exactly 1."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corners of a symbol: lower left = duration/time (and deferment m|), lower right = ages and order, upper right = periodicity, upper left = free. (x) = a person aged x; n| = term-certain."}]},{"text":[{"text":"Adopted London 1898; revised 1949 (i^(m), ä and s̈, D, Q dropped); U not adopted."}]},{"text":[{"text":"v = 1/(1 + i), d = iv = 1 - v, i = d/(1 - d), 1 + i = (1 + i^(m)/m)^m = e^δ."}]},{"text":[{"text":"a = PV of annuity, s = amount, A = assurance, E = endowment, P' valuation premium, P'' office premium, W paid-up."}]},{"text":[{"text":"Bar = continuous, circle = complete, trema = acceleration (due), [x] = select."}]},{"text":[{"text":"A_x whole life, A^1_x:n| term, A_x:n| endowment assurance, a_x:n| temporary annuity, ä_x:n| its annuity-due."}]},{"text":[{"text":"d_x = l_x - l_(x+1); q_x = d_x/l_x; p_x =$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 15, $study_guide$ 1 - q_x; l_x always falls; radix = l_0."}]},{"text":[{"text":"_np_x = l_(x+n)/l_x; m|q_x = d_(x+m)/l_x; s(x) = l_x/l_0."}]},{"text":[{"text":"e_x = (l_(x+1) + l_(x+2) + ...)/l_x = a_x at i = 0; e̊_x ≈ e_x + 0.5."}]},{"text":[{"text":"Nigeria has no local actuarial tables; insurers rely on foreign-population tables."}]}]}],"theory":{"itemId":"91ec30ca-0cb2-5a01-be7f-30fc2372ece4","question":[{"type":"paragraph","text":[{"text":"In a life table l_40 = 90,000, q_40 = 0.003 and q_41 = 0.004. Find l_41, d_41, l_42 and _2p_40."}]}]},"practice":[{"topic":"Actuarial Symbols, Notations and Life Tables","named":false}]}},{"kind":"note","itemId":"9a105d12-37e6-5be3-b0d1-70ac3d7c1996","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Actuarial Science, Insurance and the Role of Actuaries in Society","body":"What actuaries do for insurers and for society; the key insurance ideas (pooling, underwriting, hazards, reinsurance, risk management); pricing, reserving and solvency with their simple calculations; the branches, products and pension arrangements actuaries work on; where actuaries work and their career choices.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"What actuaries do for insurers and for society; the key insurance ideas (pooling, underwriting, hazards, reinsurance, risk management); pricing, reserving and solvency with their simple calculations; the branches, products and pension arrangements actuaries work on; where actuaries work and their career choices."}],"lessons":[{"number":"4.1","title":"What actuaries do for insurers and for society","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial science:","bold":true},{"text":" deals with evaluating risks and maintaining the economic stability of insurance or financial organisations, using "},{"text":"mathematics, statistics and probability","bold":true},{"text":" to anticipate future events and take preventive measures."}]},{"text":[{"text":"An actuary","bold":true},{"text":" analyses, manages and measures the financial implications of future risk; develops and validates financial models to guide decisions; and is the analytical backbone of society's financial security programmes (insurance, social security, pensions)."}]},{"text":[{"text":"Method:","bold":true},{"text":" analyse "},{"text":"past data","bold":true},{"text":", identify a "},{"text":"trend","bold":true},{"text":", predict the future, then decide how much money to set aside for future losses. Using the past is like \"driving a car by looking in the rear-view mirror\", so the actuary must also "},{"text":"quantify how the future will be different from the past","bold":true},{"text":" (e.g. the effect of a big rise in petrol prices on motor insurance costs)."}]},{"text":[{"text":"Main challenge:","bold":true},{"text":" when there is "},{"text":"no past data","bold":true},{"text":", or the data is no longer relevant because of policy or other changes (e.g. a brand-new product)."}]}]},{"type":"paragraph","text":[{"text":"What actuaries do (list):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Evaluate the likelihood of future events:","bold":true},{"text":" forecast the impact of catastrophes; calculate the expected lifetime of a retiree on a pension."}]},{"text":[{"text":"Design creative ways to reduce the likelihood of undesirable events:","bold":true},{"text":" life insurance policies, annuities, promoting safety (seat belts)."}]},{"text":[{"text":"Decrease the impact of undesirable events that do occur:","bold":true},{"text":" death benefits, retirement benefits, indemnity benefits."}]},{"text":[{"text":"Participate in corporate planning:","bold":true},{"text":" mergers and acquisitions; evaluating investment programmes."}]},{"text":[{"text":"Help insurance companies:","bold":true},{"text":" calculate rates for new insurance products; forecast and interpret underwriting results; maintain databases suited to the analysis of pricing issues."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Typical areas of actuarial work:","bold":true},{"text":" insurance (general, health, life); finance (banking, corporate, investment, pensions); data science and analytics; technology; enterprise risk; resource and environment ("},{"text":"climate change","bold":true},{"text":")."}]},{"text":[{"text":"Where else actuaries add value:","bold":true},{"text":" supporting "},{"text":"marketing teams by modelling demand","bold":true},{"text":" for a new product; supporting accounting teams with models; budgeting and forecasting; product development; managing risk."}]},{"text":[{"text":"In digital ecosystems:","bold":true},{"text":" expertise in "},{"text":"predictive modelling and optimisation","bold":true},{"text":" for quicker, smarter business risk decisions."}]}]},{"type":"table","header":[[],[{"text":"Actuary"}],[{"text":"Accountant"}],[{"text":"CFA charterholder"}]],"rows":[[[{"text":"Focus"}],[{"text":"Future events that may or may not occur"}],[{"text":"Events that have already happened"}],[{"text":"Financial reports and investments"}]],[[{"text":"Assets/liabilities"}],[{"text":"Both; "},{"text":"uniquely trained to understand liabilities","bold":true},{"text":" (they are complicated)"}],[{"text":"Reports on both"}],[{"text":"Geared towards "},{"text":"assets","bold":true}]],[[{"text":"Products"}],[{"text":"How products make money"}],[{"text":"Cost, revenue, profit"}],[{"text":"Which products or companies to "},{"text":"invest in","bold":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lagos example:","bold":true},{"text":" to predict crashes next November, the actuary studies the percentage of people in accidents in previous years, finds a trend, then "},{"text":"establishes how much each person should pay","bold":true},{"text":" so premiums cover the damages."}]},{"text":[{"text":"A death benefit paid to a family "},{"text":"decreases the impact","italic"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 16, $study_guide$:true},{"text":" of an event that has happened; a seat-belt campaign "},{"text":"reduces the likelihood or effect","italic":true},{"text":" of the event. Exams swap these two."}]},{"text":[{"text":"Valuing an insurer's long-term liabilities before a bank buys it is "},{"text":"corporate planning (mergers and acquisitions)","bold":true},{"text":"."}]},{"text":[{"text":"Actuaries do "},{"text":"not","bold":true},{"text":" decide court cases, sell door to door or repair vehicles."}]}]}]},{"number":"4.2","title":"Core insurance ideas","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Insurance company:","bold":true},{"text":" an institution that, by contract, binds itself to "},{"text":"indemnify","bold":true},{"text":" another party against specified loss in return for premiums. "},{"text":"Indemnity:","bold":true},{"text":" compensation for damages or loss."}]},{"text":[{"text":"Financial security system:","bold":true},{"text":" an arrangement in which one person takes on the obligation to provide benefits to offset undesirable economic consequences suffered by a second person, in return for payments called "},{"text":"considerations","bold":true},{"text":" (e.g. insurance products, retirement plans). It is "},{"text":"mandatory","bold":true},{"text":" if everyone in the group must take part; otherwise "},{"text":"voluntary","bold":true},{"text":"."}]},{"text":[{"text":"Insurable risk","bold":true},{"text":" criteria: (1) a potential loss; (2) that is significant; (3) loss and its economic value well defined and out of the policyholder's complete control; (4) covered losses reasonably independent. The risk must not be so large that no insurer could pay."}]},{"text":[{"text":"Peril:","bold":true},{"text":" the cause of loss (fire, flood, theft) against which cover is bought. "},{"text":"Hazard:","bold":true},{"text":" a condition that increases the probability or size of a loss."}]},{"text":[{"text":"Moral hazard:","bold":true},{"text":" an insured takes more risk knowing he will be compensated. "},{"text":"Adverse selection (antiselection):","bold":true},{"text":" people with above-average likelihood of loss are more likely to apply for or keep insurance."}]},{"text":[{"text":"Pooling:","bold":true},{"text":" forming a group of policies with similar characteristics (e.g. group size, benefit structure) to protect the insurer, based on the "},{"text":"law of large numbers","bold":true},{"text":": the larger and more homogeneous the group, the more certain the predictions. "},{"text":"Risk pool:","bold":true},{"text":" such a group of policies. "},{"text":"Risk subject:","bold":true},{"text":" the person or object involved in the insured event."}]},{"text":[{"text":"Underwriting:","bold":true},{"text":" the process by which an insurer decides "},{"text":"which people to accept and on what terms","bold":true},{"text":". "},{"text":"Underwriting factors:","bold":true},{"text":" what the insurer considers before issuing a policy and setting the premium (age, health history, occupation)."}]},{"text":[{"text":"Risk classification:","bold":true},{"text":" grouping insureds with similar underwriting factors so each group pays a fair premium."}]},{"text":[{"text":"Reinsurance:","bold":true},{"text":" another licensed (re)insurer agrees to cover all or part of a primary insurer's losses for a premium. "},{"text":"Catastrophe reinsurance:","bold":true},{"text":" pays when losses from a "},{"text":"single event","bold":true},{"text":" exceed the buyer's retention."}]},{"text":[{"text":"Mortality:","bold":true},{"text":" the incidence of "},{"text":"death","bold":true},{"text":" in a population. "},{"text":"Morbidity:","bold":true},{"text":" the rate of "},{"text":"disease","bold":true},{"text":"."}]},{"text":[{"text":"Frequency distribution:","bold":true},{"text":" how "},{"text":"many","bold":true},{"text":" claims occur. "},{"text":"Severity distribution:","bold":true},{"text":" how "},{"text":"large","bold":true},{"text":" each claim is."}]},{"text":[{"text":"Risk management:","bold":true},{"text":" identifying and assessing risk, then developing strategies to minimise, monitor and control it. "},{"text":"Ideal prioritisation:","bold":true},{"text":" greatest loss "},{"text":"and","bold":true},{"text":" greatest probability first; lower loss and lower probability later."}]},{"text":[{"text":"Risk management system","bold":true},{"text":" activities: risk identification, risk assessment, risk control, risk reporting and monitoring, risk financing. (\"Risk concealment\" is not one.)"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fire vs petrol:","bold":true},{"text":" an Onitsha shop insured against fire stores petrol beside wiring. Fire = "},{"text":"peril","bold":true},{"text":"; the stored petrol = "},{"text":"hazard","bold":true},{"text":"."}]},{"text":[{"text":"Leaving an insured car unlocked","bold":true},{"text":" = moral hazard (behaviour changes "},{"text":"after","italic":true},{"text":" cover). "},{"text":"More sick people applying for a flat-premium health plan","bold":true},{"text":" = adverse selection (who joins)."}]},{"text":[{"text":"Law of large numbers:","bold":true},{"text":" 5,000 similar traders give far more reliable predictions than 20; size and similarity, not honesty, matter."}]},{"text":[{"text":"A state that requires every employee to join its health scheme runs a "},{"text":"mandatory","bold":true},{"text":" system; a club where joining is optional runs a "},{"text":"voluntary","bold":true},{"text":" one."}]},{"text":[{"text":"Risks ranked (I) high loss, high probability; (II) low, low; (III) high loss, low probability; (IV) low loss, high probability: handle "},{"text":"I first","bold":true},{"text":", II last."}]}]}]},{"number":"4.3","title":"Pricing, reserving and solvency","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial pricing:","bold":true},{"text":" pricing risk on probabilities of l$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 17, $study_guide$oss occurrence, to develop premiums that cover losses from underwritten risks and future benefits."}]},{"text":[{"text":"Expected claim cost per policy = probability of claim × average claim"}]},{"text":[{"text":"Expected total claims = number of policies × probability × average claim"}]},{"text":[{"text":"Premium with loading = expected claim cost × (1 + loading %)"}]},{"text":[{"text":"Gross (office) premium","bold":true},{"text":" components: (1) risk premium; (2) commission; (3) allowance for other expenses; (4) allowance for premium tax; (5) profit loading. Surrender value is "},{"text":"not","bold":true},{"text":" a part."}]},{"text":[{"text":"Reserves","bold":true},{"text":" (life insurance): money held to cover "},{"text":"future policyholder benefits and claims","bold":true},{"text":" on policies already sold."}]},{"text":[{"text":"IBNR reserve:","bold":true},{"text":" estimate owed for covered losses that have occurred but "},{"text":"not yet been reported","bold":true},{"text":"."}]},{"text":[{"text":"Earned premium:","bold":true},{"text":" the part for cover already given. "},{"text":"Unearned premium:","bold":true},{"text":" premium paid for cover "},{"text":"not yet provided","bold":true},{"text":"; held in the "},{"text":"unearned premium reserve (UPR)","bold":true},{"text":"."}]},{"text":[{"text":"Unearned premium = annual premium × months of cover remaining / 12"}]},{"text":[{"text":"Loss ratio = claims incurred / premiums earned"}]},{"text":[{"text":"Solvency:","bold":true},{"text":" assets greater than the sum of debt obligations. Solvency margin = assets − liabilities"}]},{"text":[{"text":"Risk-based capital (RBC):","bold":true},{"text":" theoretical capital needed to absorb a business's risks so that it has an acceptably low chance of insolvency. "},{"text":"Capital requirement:","bold":true},{"text":" capital a bank or financial institution must hold as set by its regulator."}]},{"text":[{"text":"Experience rating:","bold":true},{"text":" adjusting a client's premium using the part of its own claims experience judged credible. "},{"text":"Credibility:","bold":true},{"text":" the relative weight given to one of two or more estimates (e.g. the group's own data versus manual rates)."}]}]},{"type":"table","header":[[{"text":"Actuary"}],[{"text":"Main job"}]],"rows":[[[{"text":"Pricing actuary","bold":true}],[{"text":"Sets the premium: decides the appropriate \"just a little more\" (loading) and validates the expected number and amount of claims"}]],[[{"text":"Valuation actuary","bold":true}],[{"text":"Calculates reserves (liabilities) for policies already sold"}]],[[{"text":"Pension actuary","bold":true}],[{"text":"Projects members' benefits from ages and salaries, allowing for leavers and pay rises"}]],[[{"text":"Consulting actuary","bold":true}],[{"text":"Advises client organisations from outside, often on pensions"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Simulation:","bold":true},{"text":" used to "},{"text":"model potential outcomes under uncertainty","bold":true},{"text":". A "},{"text":"single projection","bold":true},{"text":" uses one set of assumptions, so it "},{"text":"may not capture the full range of scenarios","bold":true},{"text":". Extra scenarios show the "},{"text":"range of outcomes under different conditions","bold":true},{"text":". The "},{"text":"mean","bold":true},{"text":" measures central tendency of the output; range, variance and standard deviation measure spread."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (pricing).","italic":true},{"text":" An insurer covers 1,000 keke drivers. Probability of a claim = 0.05, average claim = ₦300,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Expected cost per driver = 0.05 × ₦300,000 = "},{"text":"₦15,000","bold":true},{"text":"."}]},{"text":[{"text":"Expected total claims = 1,000 × ₦15,000 = "},{"text":"₦15,000,000","bold":true},{"text":"."}]},{"text":[{"text":"With a 25% loading: ₦15,000 × 1.25 = "},{"text":"₦18,750","bold":true},{"text":"."}]},{"text":[{"text":"Trap: the total (₦15,000,000) or the loading alone (₦3,750) appear as wrong options."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2 (unearned premium).","italic":true},{"text":" Premium ₦240,000 paid on 1 April 2025 for 12 months; year-end 31 December 2025."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Months elapsed = 9 (April to December). Earned = ₦240,000 × 9/12 = ₦180,000."}]},{"text":[{"text":"Months remaining = 3. Unearned = ₦240,000 × 3/12 = "},{"text":"₦60,000","bold":true},{"text":"."}]},{"text":[{"text":"Count the months "},{"text":"left","italic":true},{"text":", not the months gone."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3 (loss ratio and solvency).","italic":true},{"text":" Claims incurred ₦30m, premiums earned ₦48m: loss ratio = 30/48 = "},{"text":"62.5%","bold":true},{"text":". Assets ₦5.0bn, liabilities ₦4.2bn: solvency margin = "},{"text":"₦0.8bn","bold":true},{"text":" (solvent, since assets exceed liabilities). Never divide premiums by claims."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"IBNR case:","bold":true},{"text":" floods on 29 December, year-end 31 December, losses not yet reported: the provision is IBNR, not UPR."}]},{"text":[{"text":"Ten years of reliable bank data earns high "},{"text":"credibility","bold":true},{"text":"; a tiny start-up relies on manual rates."}]}]}]},{"number":"4.4","title":"Branches, products and where actuaries work","mustKnow":[{"type":"paragraph","text":[{"text":"8 specialisations:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Health and Care"}]},{"text":[{"text":"Life Insurance"}]},{"text":[{"text":"Pensions"}]},{"text":[{"text":"Investment and Finance"}]},{"text":[{"text":"Financial Derivatives"}]},{"text":[{"text":"General Insurance: Reserving"}]},{"text":[{"text":"General Insurance: Pricing"}]},{"text":[{"text":"Ent$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 18, $study_guide$erprise Risk Management"}]}]},{"type":"paragraph","text":[{"text":"Most common industries:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Insurance:","bold":true},{"text":" property (home) and casualty (auto); life and annuities."}]},{"text":[{"text":"Employee benefits:","bold":true},{"text":" retirement benefits, health benefits, social security."}]},{"text":[{"text":"Financial services:","bold":true},{"text":" banks, investing, risk management, mergers and acquisitions."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuaries are largely employed by "},{"text":"insurance companies and consulting firms","bold":true},{"text":", in: life, annuities and mutual funds; health; pensions; property and casualty."}]},{"text":[{"text":"Life insurance:","bold":true},{"text":" term and permanent products giving "},{"text":"death benefit protection","bold":true},{"text":"."}]},{"text":[{"text":"Annuity:","bold":true},{"text":" fixed or variable products; customer pays a lump sum or series of payments now for "},{"text":"periodic payments beginning immediately or in the future","bold":true},{"text":"."}]},{"text":[{"text":"Mutual fund:","bold":true},{"text":" "},{"text":"pools the assets of multiple investors","bold":true},{"text":" and buys securities towards a common, pre-defined goal."}]},{"text":[{"text":"Pension:","bold":true},{"text":" "},{"text":"steady income","bold":true},{"text":", typically a guaranteed annuity, to a "},{"text":"retired or disabled employee","bold":true},{"text":" under legal or contractual terms."}]},{"text":[{"text":"Term life:","bold":true},{"text":" pays only if death occurs within a set period. "},{"text":"Whole life:","bold":true},{"text":" set death benefit, level premium, guaranteed cash values. "},{"text":"Key person insurance:","bold":true},{"text":" life cover on a key employee or owner; the "},{"text":"business is the beneficiary","bold":true},{"text":"."}]},{"text":[{"text":"Casualty insurance:","bold":true},{"text":" broad non-life, non-health cover against loss of property, damage or liabilities (motor, liability, theft)."}]},{"text":[{"text":"Lapse:","bold":true},{"text":" policy ends because the renewal premium is not paid within the grace period. "},{"text":"Surrender value:","bold":true},{"text":" what the policyholder receives on choosing to stop the policy."}]},{"text":[{"text":"Health segments (employers):","bold":true},{"text":" small group 2 to 50 employees; middle market 51 to 3,000; national accounts 3,001+."}]}]},{"type":"paragraph","text":[{"text":"Typical projects:","bold":true}]},{"type":"table","header":[[{"text":"Area"}],[{"text":"Project"}]],"rows":[[[{"text":"Life insurance"}],[{"text":"Designing and pricing products; impact of a disease (e.g. AIDS) on mortality tables"}]],[[{"text":"Property and casualty"}],[{"text":"Cost of personal auto or homeowners cover in an area; impact of global warming"}]],[[{"text":"Health benefits"}],[{"text":"Setting HMO premium rates"}]],[[{"text":"Retirement systems"}],[{"text":"Pricing the cost of increasing retirement benefits"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Branch by task:","bold":true},{"text":" 10-year term assurance priced on mortality = "},{"text":"life actuary","bold":true},{"text":"; HMO premiums for employers = "},{"text":"health actuary","bold":true},{"text":"; employer's yearly payments into a DB scheme = "},{"text":"pension actuary","bold":true},{"text":"; matching assets to annuity payment timing = "},{"text":"investment actuary","bold":true},{"text":"; reserves for motor and fire claims not yet settled = "},{"text":"general insurance reserving","bold":true},{"text":"."}]},{"text":[{"text":"Motor insurance on a commercial bus is "},{"text":"general (non-life)","bold":true},{"text":"; whole life, term life and annuities are life business."}]},{"text":[{"text":"A company with 120 staff is "},{"text":"middle market","bold":true},{"text":"."}]},{"text":[{"text":"A retiree paying ₦10,000,000 once for monthly income for life has bought an "},{"text":"annuity","bold":true},{"text":"."}]}]}]},{"number":"4.5","title":"Pensions, social security and government","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Defined benefit (DB):","bold":true},{"text":" benefit set by scheme rules from "},{"text":"pay, years of service, age at retirement","bold":true},{"text":", independently of contributions; the "},{"text":"employer","bold":true},{"text":" bears the investment risk."}]},{"text":[{"text":"Defined contribution (DC):","bold":true},{"text":" benefit depends on contributions paid plus investment return; the "},{"text":"employee","bold":true},{"text":" bears the investment risk."}]},{"text":[{"text":"DB pension = accrual rate × years of service × final salary"}]},{"text":[{"text":"DC yearly payment in = (employee + employer monthly contribution) × 12"}]},{"text":[{"text":"Pay-as-you-go:","bold":true},{"text":" benefits paid out of current revenue, with "},{"text":"no funding","bold":true},{"text":" for future liabilities."}]},{"text":[{"text":"Funding objective:","bold":true},{"text":" assesses the level of funding a pension plan needs to provide its members' benefits."}]},{"text":[{"text":"Active member:","bold":true},{"text":" still contributing and building benefits. "},{"text":"Deferred member:","bold":true},{"text":" has left before pension age with preserved benefits paid at retirement."}]},{"text":[{"text":"Nigeria:","bold":true},{"text":" the "},{"text":"Contributory Pension Scheme","bold":true},{"text":" (Pension Reform Act 2014) is "},{"text":"DC","bold":true},{"text":": each worker has a "},{"text":"Retirement Savings Account (RSA)","bold":true},{"text":"; minimum contributions are 8% (employee) and 10% (employer) of monthly emoluments. It is regulated by "},{"text":"PenCom","bold":true},{"text":". Insurance is regulated by "},{"text":"NAICOM","bold":true},{"text":"."}]}]},{"ty$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 19, $study_guide$pe":"paragraph","text":[{"text":"Roles in government, social security, banking and regulation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Costing social security and public-service pensions (e.g. a 10% rise in civil servants' benefits = "},{"text":"retirement systems","bold":true},{"text":" work)."}]},{"text":[{"text":"Supporting the regulator ("},{"text":"NAICOM","bold":true},{"text":") in setting and reviewing "},{"text":"capital and reserving requirements","bold":true},{"text":"."}]},{"text":[{"text":"In banking, measuring the risks behind regulatory "},{"text":"capital requirements","bold":true},{"text":"."}]},{"text":[{"text":"Measuring insurance liabilities under "},{"text":"IFRS 17","bold":true},{"text":", which "},{"text":"increases demand","bold":true},{"text":" for actuaries."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 4 (DB).","italic":true},{"text":" Accrual 1.5% per year, 30 years' service, final salary ₦3,600,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Pension = 0.015 × 30 × ₦3,600,000 = "},{"text":"₦1,620,000 a year","bold":true},{"text":"."}]},{"text":[{"text":"Trap: forgetting years of service gives ₦54,000."}]}]},{"type":"paragraph","text":[{"text":"Worked example 5 (DC).","italic":true},{"text":" Monthly pay ₦300,000; employee 8% = ₦24,000; employer 10% = ₦30,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Monthly total = ₦54,000; yearly = ₦54,000 × 12 = "},{"text":"₦648,000","bold":true},{"text":" (ignoring returns and charges)."}]},{"text":[{"text":"Trap: giving only one month, or only one side's contribution."}]},{"text":[{"text":"Nigeria (2022):","bold":true},{"text":" few qualified actuaries (about 19 Fellows) against 56 insurers, no local actuarial tables, and plans for risk-based capital and IFRS 17: demand exceeds supply."}]}]}]},{"number":"4.6","title":"Career choices for an actuary","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"3 main bodies:","bold":true},{"text":" "},{"text":"Institute and Faculty of Actuaries (IFoA)","bold":true},{"text":", "},{"text":"Society of Actuaries (SOA)","bold":true},{"text":", "},{"text":"Casualty Actuarial Society (CAS)","bold":true},{"text":". ASSA (South Africa) is another."}]},{"text":[{"text":"CAS covers property and casualty (general) only","bold":true},{"text":"; SOA covers life, pensions and health; IFoA and ASSA cover all four."}]},{"text":[{"text":"Two levels","bold":true},{"text":" (SOA, CAS): "},{"text":"Associate","bold":true},{"text":" (ASA, ACAS) first, then "},{"text":"Fellow","bold":true},{"text":" (FSA, FCAS); both by examinations taken while working."}]},{"text":[{"text":"IFoA specialist principles:","bold":true},{"text":" SP1 Health and Care; SP2 Life Insurance; SP4 Pensions and Other Benefits; SP5 Investment and Finance; SP6 Financial Derivatives; "},{"text":"SP7 General Insurance Reserving and Capital Modelling","bold":true},{"text":"; SP8 General Insurance Pricing; SP9 Enterprise Risk Management."}]}]},{"type":"paragraph","text":[{"text":"Skills needed:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Mathematical and analytical skills"}]},{"text":[{"text":"Project management and problem-solving skills"}]},{"text":[{"text":"Excellent communication skills (oral and written)"}]},{"text":[{"text":"Strong business sense and commercial awareness"}]},{"text":[{"text":"Self-motivation (exams while working)"}]},{"text":[{"text":"Ambition and ability to work in a team"}]}]},{"type":"paragraph","text":[{"text":"Reasons to become an actuary:","bold":true},{"text":" job security; good pay; recognised qualifications; "},{"text":"highly transferable skills","bold":true},{"text":"; "},{"text":"international opportunities","bold":true},{"text":"; \""},{"text":"earn while you learn","bold":true},{"text":"\"; early advancement is largely "},{"text":"exam-based","bold":true},{"text":"; dynamic work."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Working alone and avoiding communication is "},{"text":"not","bold":true},{"text":" a required skill. Advancement does "},{"text":"not","bold":true},{"text":" depend only on length of service."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Actuarial science evaluates risk with mathematics, statistics and probability; actuaries use past data but must quantify how the future will differ."}]},{"text":[{"text":"Actuaries evaluate likelihood, reduce likelihood, decrease impact, join corporate planning, and help insurers price and forecast."}]},{"text":[{"text":"Peril causes loss, hazard increases it; moral hazard is behaviour after cover, adverse selection is who applies."}]},{"text":[{"text":"Pooling relies on the law of large numbers; underwriting decides who to accept and on what terms."}]},{"text":[{"text":"Expected claim cost = probability × average claim; premium = cost × (1 + loading)."}]},{"text":[{"text":"Unearned premium = premium × months left / 12; loss ratio = claims incurred / premiums earned; solvency margin = assets − liabilities."}]},{"text":[{"text":"DB: employer bears risk; DC (Nigeria's CPS, PenCom): employee bears risk."}]},{"text":[{"text":"Bodies: IFoA, SOA, CAS (P&C only); Associate then Fellow."}]}]}],"theory":{"itemId":"8368a089-9a1b-5585-8838-55f0fc3e0e42","question":[{"type":"paragraph","text":[{"text":"An insurer covers 400 Lagos shop owners against burglary for one year. The probability of a claim is 0.02 per shop and the average claim is ₦500,000 (at most one claim each). It adds a 30% loading. Find (a) the risk premium per shop, (b) the gross premium per shop, (c) the expected loss ratio if claims come in as expected."}]}]},"practice":[{"topic":"Actuarial Science, Insurance and the Role of Actuaries","named":false}]}},{"kind":"note","itemId":"0a04d483-78ba-5a05-8218-8a4b5def9d21","sourceKey":"guide-topic:5","position":5,"payload":{"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 20, $study_guide$title":"Time Value of Money: Compound Interest and Discounting","body":"The time value of money; simple interest and simple discount; compound interest, accumulation and discounting with v; the effective rate of discount d; nominal rates i^(m) and d^(m); the force of interest δ; the relationships among i, d, v and δ; changing rates; equations of value; solving for time and rate.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The time value of money; simple interest and simple discount; compound interest, accumulation and discounting with v; the effective rate of discount d; nominal rates i^(m) and d^(m); the force of interest δ; the relationships among i, d, v and δ; changing rates; equations of value; solving for time and rate."}],"lessons":[{"number":"5.1","title":"Time value of money, simple interest and simple discount","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Time value of money (TVM):","bold":true},{"text":" money available today is worth more than the same amount in the future, because money received now can be invested to earn interest. So ₦100 today is worth more than ₦100 a year from now."}]},{"text":[{"text":"Principal (P):","bold":true},{"text":" the amount originally invested, which attracts interest."}]},{"text":[{"text":"Accumulation (compounding):","bold":true},{"text":" moving money forward in time (finding a future or accumulated value). "},{"text":"Discounting:","bold":true},{"text":" moving money back in time (finding the present value of future cash flows)."}]},{"text":[{"text":"The future value of an investment depends on "},{"text":"all three","bold":true},{"text":": the principal, the interest rate and the time."}]},{"text":[{"text":"Simple interest:","bold":true},{"text":" interest is earned only on the original principal, so the interest is the "},{"text":"same every year","bold":true},{"text":". At rate r per annum, 1 grows to "},{"text":"1 + rt","bold":true},{"text":" after t years."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A = P(1 + rt) and interest I = Prt."}]},{"text":[{"text":"Present value under simple interest: P = A/(1 + rt)."}]},{"text":[{"text":"Time in months: t = months/12."}]}]}]},{"text":[{"text":"Simple discount:","bold":true},{"text":" at rate of simple discount d per annum, the value now of an amount A payable at time t is "},{"text":"P = A(1 − dt)","bold":true},{"text":". So an amount P invested now accumulates to "},{"text":"A = P/(1 − dt)","bold":true},{"text":", and 1 invested for one year accumulates to "},{"text":"1/(1 − d)","bold":true},{"text":"."}]},{"text":[{"text":"Solving simple interest for the rate: r = (A/P − 1)/t. For the time: t = (A/P − 1)/r."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Simple interest, worked:","bold":true},{"text":" ₦50,000 at 12% simple interest for 3 years. I = 50,000 × 0.12 × 3 = ₦18,000; A = ₦68,000. Equally, ₦1,000 at 8% simple for 5 years: A = 1,000(1 + 0.08 × 5) = ₦1,400."}]},{"text":[{"text":"Part of a year:","bold":true},{"text":" ₦60,000 at 10% for 8 months: I = 60,000 × 0.10 × 8/12 = ₦4,000."}]},{"text":[{"text":"Finding the rate:","bold":true},{"text":" ₦30,000 grows to ₦39,000 in 4 years. r = (39,000/30,000 − 1)/4 = 0.30/4 = "},{"text":"7.5%","bold":true},{"text":"."}]},{"text":[{"text":"Finding the time:","bold":true},{"text":" ₦40,000 grows to ₦52,000 at 6%. t = (1.3 − 1)/0.06 = "},{"text":"5 years","bold":true},{"text":"."}]},{"text":[{"text":"Present value at simple interest:","bold":true},{"text":" a debt of ₦20,000 is due in 4 years and you can invest at 5% simple. Invest 20,000/(1 + 0.05 × 4) = 20,000/1.2 = "},{"text":"₦16,666.67","bold":true},{"text":" now."}]},{"text":[{"text":"Simple discount, present value:","bold":true},{"text":" a bill of ₦80,000 due in 1.5 years at 8% simple discount: P = 80,000(1 − 0.08 × 1.5) = 80,000 × 0.88 = "},{"text":"₦70,400","bold":true},{"text":"."}]},{"text":[{"text":"Simple discount, accumulation:","bold":true},{"text":" ₦1,000 invested for 5 years at 8% simple discount accumulates to 1,000/(1 − 0.4) = "},{"text":"₦1,666.67","bold":true},{"text":" (2 d.p.). ₦5,000 for 2 years at 10% gives 5,000/0.8 = ₦6,250. One naira for one year at 10% simple discount gives 1/0.9 = 1.1111."}]},{"text":[{"text":"Trap:","bold":true},{"text":" under simple discount you "},{"text":"divide","bold":true},{"text":" by (1 − dt) to accumulate and "},{"text":"multiply","bold":true},{"text":" by (1 − dt) to find the value now. Do not use 1 + dt."}]},{"text":[{"text":"Nigerian Treasury Bills are sold at a discount to their face value, so the buyer pays less now and receives the full face value at maturity."}]}]}]},{"number":"5.2","title":"Compound interest, accumulation and the discount factor v","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Compound interest:","bold":true},{"text":" interest is earned on the principal "},{"text":"and","bold":true},{"text":" on interest already earned (interest is added and itself earns interest)."}]},{"text":[{"text":"Effective rate of interest i:","bold":true},{"text":" the total interest earned on 1 in a period (usually a year), assuming interest is reinvested as it falls due."}]},{"text":[{"text":"Accumulation factor:","bold":true},{"text":" (1 + i)^n = the accumulated value at time n of 1 invested at time 0."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"AV = P(1 + i)^n","bold":true},{"text":"; interest earned = P(1 + i)^n − P."}]}]}]},{"text":[{"text":"Discount factor:","bold":true},{"text":" "},{"text":"v = (1 + i)^−1 = 1/(1 + i)","bold":true},{"text":", the present value of 1 due one period hence."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"v^n = (1 + i)^−n","bold":true},{"text":" = the present value of 1 due at the end of n years."}]},{"text":[{"text":"PV = FV/(1 + i)^n = FV × v^n","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Moving a payment:","bold":true},$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 21, $study_guide${"text":" value at time t of X due at time s = X(1 + i)^(t − s). If t is earlier than s, this is X × v^(s − t). E.g. value at time 3 of a payment due at time 7 = payment × v^4."}]},{"text":[{"text":"The later a payment, the "},{"text":"smaller","bold":true},{"text":" its present value, because v^n falls as n increases."}]},{"text":[{"text":"n need not be whole: 2 years 6 months means n = 2.5."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Simple interest"}],[{"text":"Compound interest"}]],"rows":[[[{"text":"Interest earned on"}],[{"text":"principal only"}],[{"text":"principal and past interest"}]],[[{"text":"1 grows to"}],[{"text":"1 + rt"}],[{"text":"(1 + i)^t"}]],[[{"text":"Growth pattern"}],[{"text":"linear (straight line)"}],[{"text":"geometric (exponential)"}]],[[{"text":"Interest each year"}],[{"text":"the same"}],[{"text":"rises every year"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"At the same rate: "},{"text":"t = 1 year","bold":true},{"text":", both give 1 + i (equal); "},{"text":"t > 1","bold":true},{"text":", compound gives more; "},{"text":"t < 1","bold":true},{"text":", compound gives "},{"text":"less","bold":true},{"text":" than simple."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Year-by-year table:","bold":true},{"text":" ₦100 at 5% compound for 3 years (2 d.p.)."}]}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Principal at start"}],[{"text":"Interest at end"}],[{"text":"Accumulation at end"}]],"rows":[[[{"text":"1"}],[{"text":"100.00"}],[{"text":"5.00"}],[{"text":"105.00"}]],[[{"text":"2"}],[{"text":"105.00"}],[{"text":"5.25"}],[{"text":"110.25"}]],[[{"text":"3"}],[{"text":"110.25"}],[{"text":"5.51"}],[{"text":"115.76"}]]]},{"type":"paragraph","text":[{"text":"Check: 100 × 1.05^3 = 115.7625 = ₦115.76. Interest rises each year because it is earned on a growing balance. A thrift cooperative that credits interest yearly and lets it earn interest is using compound interest."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Accumulated value:","bold":true},{"text":" ₦120,000 at 9% effective for 5 years. 1.09^5 = 1.53862395; AV = "},{"text":"₦184,634.87","bold":true},{"text":"; interest earned = ₦64,634.87."}]},{"text":[{"text":"Present value:","bold":true},{"text":" how much must be invested now to accumulate ₦200 in 3 years at 5%? X × 1.05^3 = 200, so X = 200/1.157625 = "},{"text":"₦172.77","bold":true},{"text":"."}]},{"text":[{"text":"Value at an intermediate date:","bold":true},{"text":" ₦400,000 is due at the end of year 6; at 8%, its value at the end of year 2 is 400,000 × v^4 = 400,000 × 0.73502985 = "},{"text":"₦294,011.94","bold":true},{"text":"."}]},{"text":[{"text":"Fractional period:","bold":true},{"text":" ₦20,000 for 3 years 9 months at 10%: 20,000 × 1.1^3.75 = "},{"text":"₦28,592.53","bold":true},{"text":"."}]},{"text":[{"text":"Compound versus simple over 2 years:","bold":true},{"text":" ₦200,000 at 15%. Compound interest = 200,000(1.15^2 − 1) = ₦64,500; simple interest = ₦60,000. Compound exceeds simple by ₦4,500 (= P × i^2 for 2 years)."}]},{"text":[{"text":"Under one year simple wins:","bold":true},{"text":" ₦100,000 for 3 months at 20%. Simple: 100,000(1 + 0.2 × 0.25) = ₦105,000. Compound: 100,000 × 1.2^0.25 = ₦104,663.51. Simple gives ₦336.49 more."}]},{"text":[{"text":"Interest-table values","bold":true},{"text":" (learn to get these on your calculator): at 6%, (1.06)^10 = 1.79085 and v^10 = 0.55839; at 3.5%, (1.035)^10 = 1.41060."}]},{"text":[{"text":"Trap:","bold":true},{"text":" PV = FV(1 + i)^n is accumulation, not discounting; PV = FV/(1 + ni) is simple interest. The compound-interest PV is FV/(1 + i)^n."}]},{"text":[{"text":"Actuaries valuing pension liabilities (supervised by PenCom) and insurance reserves (supervised by NAICOM) discount the future payments to today with v^n."}]}]}]},{"number":"5.3","title":"The effective rate of discount d and the links among i, d and v","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Effective rate of discount d:","bold":true},{"text":" the discount on 1 due a year hence; that is, interest for the year paid at the "},{"text":"start","bold":true},{"text":" of the year. (i is interest paid at the "},{"text":"end","bold":true},{"text":" of the year.)"}]},{"text":[{"text":"Correct formulae (learn all of them):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"d = i/(1 + i)","bold":true}]},{"text":[{"text":"d = iv","bold":true}]},{"text":[{"text":"d = 1 − v","bold":true},{"text":", so "},{"text":"v = 1 − d","bold":true}]},{"text":[{"text":"i = d/(1 − d)","bold":true}]}]}]},{"text":[{"text":"d < i","bold":true},{"text":" whenever i > 0."}]},{"text":[{"text":"PV of X due in n years at discount rate d: "},{"text":"X(1 − d)^n = X v^n","bold":true},{"text":"."}]},{"text":[{"text":"Amount of discount","bold":true},{"text":" on a bill of face value X due in one year = X − Xv = "},{"text":"X × d","bold":true},{"text":"."}]},{"text":[{"text":"Not","bold":true},{"text":" correct: d = i/(1 − i); v = 1 + d."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"From i to d:","bold":true},{"text":" i = 8%. d = 0.08/1.08 = 0.074074 = "},{"text":"7.41%","bold":true},{"text":" (2 d.p.). Likewise i = 5% gives d = 0.047619 and i = 2.5% gives d = 2.44%."}]},{"text":[{"text":"From d to i:","bold":true},{"text":" d = 6%. i = 0.06/0.94 = 0.063830 = "},{"text":"6.38%","bold":true},{"text":"."}]},{"text":[{"text":"PV using d:","bold":true},{"text":" ₦300,000 due in 3 years at d = 4%: 300,000 × 0.96^3 = "},{"text":"₦265,420.80","bold":true},{"text":"."}]},{"text":[{"text":"Discount on a bill:","bold":true},{"text":" a bill of ₦250,000 due in one year, i = 10%. d = 0.1/1.1 = 0.090909; discount = 250,000 × 0.1/1.1 = "},{"text":"₦22,727.27","bold":true},{"text":"; present value = 250,000/1.1 = ₦227,272.73. Check: 227,272.73 + 22,727.27 = 250,000."}]},{"text":[{"text":"Trap:","$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 22, $study_guide$bold":true},{"text":" the amount of discount is face × d, not face × i (₦25,000 here would be wrong)."}]}]}]},{"number":"5.4","title":"Nominal rates of interest and discount; equivalent rates","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nominal rate of interest i^(m):","bold":true},{"text":" a rate per annum "},{"text":"convertible (compounded, payable) m times a year","bold":true},{"text":". The effective rate per m-th of a year is "},{"text":"i^(m)/m","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"m = 2 half-yearly, 4 quarterly, 12 monthly, 365 daily."}]}]}]},{"text":[{"text":"Equivalent rates:","bold":true},{"text":" two rates are equivalent when they give the "},{"text":"same accumulated value","bold":true},{"text":" from the same principal over the same period."}]},{"text":[{"text":"Key equation: "},{"text":"1 + i = (1 + i^(m)/m)^m","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nominal to effective: "},{"text":"i = (1 + i^(m)/m)^m − 1","bold":true}]},{"text":[{"text":"Effective to nominal: "},{"text":"i^(m) = m[(1 + i)^(1/m) − 1]","bold":true}]}]}]},{"text":[{"text":"AV with a nominal rate:","bold":true},{"text":" A = P(1 + i^(m)/m)^(mn), n in years. "},{"text":"PV:","bold":true},{"text":" P = A(1 + i^(m)/m)^−(mn)."}]},{"text":[{"text":"Effective rate per sub-period","bold":true},{"text":" from an annual effective rate: (1 + i)^(1/m) − 1. From one period to a longer one: e.g. monthly j to quarterly = (1 + j)^3 − 1."}]},{"text":[{"text":"Nominal rate of discount d^(m):","bold":true},{"text":" discount convertible m times a year; "},{"text":"1 − d = (1 − d^(m)/m)^m = v","bold":true},{"text":"."}]},{"text":[{"text":"For a fixed nominal rate, the effective rate "},{"text":"rises","bold":true},{"text":" as m rises, towards a limit e^(i^(m)) − 1."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nominal to effective:","bold":true},{"text":" 6% p.a. payable half-yearly. ₦1,000 after 2 years: 1,000(1 + 0.06/2)^4 = 1,000 × 1.03^4 = "},{"text":"₦1,125.51","bold":true},{"text":". Effective annual rate: (1.03)^2 − 1 = "},{"text":"0.0609 = 6.09%","bold":true},{"text":"."}]},{"text":[{"text":"12% convertible quarterly: i = 1.03^4 − 1 = "},{"text":"12.55%","bold":true},{"text":". 24% convertible monthly: 2% per month, i = 1.02^12 − 1 = "},{"text":"26.82%","bold":true},{"text":" (not 24%)."}]},{"text":[{"text":"Table for 10%","bold":true},{"text":" (5 d.p.):"}]}]},{"type":"table","header":[[{"text":"m"}],[{"text":"Effective i when i^(m) = 10%"}],[{"text":"Nominal i^(m) when i = 10%"}]],"rows":[[[{"text":"1"}],[{"text":"0.10000"}],[{"text":"0.10000"}]],[[{"text":"2"}],[{"text":"0.10250"}],[{"text":"0.09762"}]],[[{"text":"4"}],[{"text":"0.10381"}],[{"text":"0.09645"}]],[[{"text":"6"}],[{"text":"0.10426"}],[{"text":"0.09607"}]],[[{"text":"12"}],[{"text":"0.10471"}],[{"text":"0.09569"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"More frequent compounding, same nominal 6%:","bold":true},{"text":" ₦10,000 for 10 years (to the nearest kobo): m = 1: ₦17,908.48; m = 2: ₦18,061.11; m = 4: ₦18,140.18; m = 12: ₦18,193.97; m = 365: ₦18,220.29. Note 6% \"compounded annually\" is just 1.06^10."}]},{"text":[{"text":"Effective to nominal:","bold":true},{"text":" i = 21% gives i^(2) = 2(1.21^0.5 − 1) = 2(0.1) = "},{"text":"20%","bold":true},{"text":"."}]},{"text":[{"text":"Sub-period rates:","bold":true},{"text":" i = 12% a year gives (1.12)^(1/12) − 1 = 0.9489% ≈ "},{"text":"0.95% per month","bold":true},{"text":". 2% per month gives 1.02^3 − 1 = "},{"text":"6.12% per quarter","bold":true},{"text":"."}]},{"text":[{"text":"Nominal to nominal:","bold":true},{"text":" i^(4) = 8% means 2% a quarter. Half-yearly: (1.02)^2 = 1.0404, so i^(2) = 2 × 0.0404 = "},{"text":"8.08%","bold":true},{"text":"."}]},{"text":[{"text":"AV:","bold":true},{"text":" ₦150,000 for 2 years at 12% convertible monthly: 150,000 × 1.01^24 = "},{"text":"₦190,460.20","bold":true},{"text":". 18 months would be 1.01^18."}]},{"text":[{"text":"PV:","bold":true},{"text":" ₦600,000 due in 3 years at 8% convertible quarterly: 600,000 × 1.02^−12 = "},{"text":"₦473,095.91","bold":true},{"text":"."}]},{"text":[{"text":"Nominal discount:","bold":true},{"text":" d^(2) = 10% means 5% each half-year. PV of ₦400,000 due in a year = 400,000 × 0.95^2 = "},{"text":"₦361,000","bold":true},{"text":". d^(4) = 8% gives d = 1 − 0.98^4 = "},{"text":"7.76%","bold":true},{"text":" (lower than 8%)."}]},{"text":[{"text":"Solving for a nominal rate:","bold":true},{"text":" ₦60,000 grows to ₦75,000 in 3 years, monthly compounding. (1 + j)^36 = 1.25, so j = 1.25^(1/36) − 1 and i^(12) = 12j = "},{"text":"7.46%","bold":true},{"text":"."}]},{"text":[{"text":"Comparing offers:","bold":true},{"text":" Bank A pays 12% convertible monthly, i = 1.01^12 − 1 = 12.68%; Bank B pays 12.5% effective. Bank A is better. Always compare "},{"text":"effective","bold":true},{"text":" rates."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"24% per annum convertible monthly\" is i^(12) = 24%, 2% per month. It is not an effective 24%, a force of interest, or a discount rate."}]}]}]},{"number":"5.5","title":"The force of interest δ","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Force of interest δ (delta):","bold":true},{"text":" the instantaneous rate of growth; the limit of the nominal rate i^(m) as m tends to infinity, i.e. a nominal rate compounding continuously (\"compounded continuously\" means a force of interest)."}]},{"text":[{"text":"In international actuarial notation the Greek letter "},{"text":"δ","bold":true},{"text":" denotes the force of interest."}]},{"text":[{"text":"Relationships:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"1 + i = e^δ","bold":true}]},{"text":[{"text":"δ = ln(1 + i)","bold":true}]},{"text":[{"text":"v = e^−δ","bold":true}]},{"text":[{"text":"d = 1 $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 23, $study_guide$− e^−δ","bold":true}]},{"text":[{"text":"i^(m) = m(e^(δ/m) − 1)"}]}]}]},{"text":[{"text":"AV = P e^(δn)","bold":true},{"text":"; "},{"text":"PV = A e^−(δn)","bold":true},{"text":"."}]},{"text":[{"text":"Not","bold":true},{"text":" correct: δ = e^i − 1."}]},{"text":[{"text":"Ordering","bold":true},{"text":" for any positive i: "},{"text":"d < d^(m) < δ < i^(m) < i","bold":true},{"text":"; in detail d < d^(2) < d^(12) < δ < i^(12) < i^(2) < i."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Effective to force:","bold":true},{"text":" i = 10%: δ = ln 1.1 = "},{"text":"0.09531","bold":true},{"text":". Half-yearly nominal 10%: (1.05)^2 = 1.1025, δ = ln 1.1025 = 0.09758. 10% effective per half-year: (1.1)^2 = 1.21, δ = ln 1.21 = 0.19062 p.a. Similarly 8% effective gives δ = 0.0770, and 5% per quarter gives δ = 4 ln 1.05 = 0.1952 p.a."}]},{"text":[{"text":"Force to others:","bold":true},{"text":" δ = 8%. i = e^0.08 − 1 = "},{"text":"8.33%","bold":true},{"text":"; v = e^−0.08 = 0.9231; d = 1 − 0.9231 = 7.69%. δ = 10% gives i^(12) = 12(e^(0.1/12) − 1) = 10.04%."}]},{"text":[{"text":"AV:","bold":true},{"text":" ₦300,000 for 3 years at δ = 10% (or 10% compounded continuously): 300,000 e^0.3 = "},{"text":"₦404,957.64","bold":true},{"text":"."}]},{"text":[{"text":"PV:","bold":true},{"text":" ₦500,000 due in 4 years at δ = 6%: 500,000 e^−0.24 = "},{"text":"₦393,313.93","bold":true},{"text":"."}]},{"text":[{"text":"Dates:","bold":true},{"text":" a loan from 1 March 2020 to 1 March 2025 runs exactly 5 years, so use n = 5."}]},{"text":[{"text":"Ordering check at i = 10%:","bold":true},{"text":" d 0.09091 < d^(2) 0.09307 < d^(12) 0.09493 < δ 0.09531 < i^(12) 0.09569 < i^(2) 0.09762 < i 0.10000."}]},{"text":[{"text":"A fixed nominal 10% with m rising gives effective rates rising towards e^0.1 − 1 = 10.52%."}]},{"text":[{"text":"Trap:","bold":true},{"text":" δ is the natural log (ln) of 1 + i, not of i, and it is always below i."}]}]}]},{"number":"5.6","title":"Changing rates, equations of value, solving for time and rate","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Changing rates:","bold":true},{"text":" multiply the accumulation factors for each period. 1 invested for 3 years at i_1 then 2 years at i_2 grows to (1 + i_1)^3(1 + i_2)^2. Discount by dividing by the same factors."}]},{"text":[{"text":"For a "},{"text":"single sum","bold":true},{"text":", the "},{"text":"order","bold":true},{"text":" of the rates does not matter (multiplication). With "},{"text":"further payments","bold":true},{"text":" at later dates, the order matters."}]},{"text":[{"text":"Equation of value:","bold":true},{"text":" set the value of what is paid in equal to the value of what is paid out, "},{"text":"with every payment valued at the same date","bold":true},{"text":". Under compound interest "},{"text":"any comparison date","bold":true},{"text":" gives the same answer."}]},{"text":[{"text":"Equivalent single payment","bold":true},{"text":" at time t: accumulate earlier payments to t and discount later ones to t."}]},{"text":[{"text":"Solving for time:","bold":true},{"text":" n = ln(A/P)/ln(1 + i). Under a force δ: n = ln(A/P)/δ. Doubling time: n = ln 2/ln(1 + i), or ln 2/δ."}]},{"text":[{"text":"Solving for the rate (one payment):","bold":true},{"text":" i = (A/P)^(1/n) − 1. With two payments a year apart, solve a "},{"text":"quadratic","bold":true},{"text":" in x = 1 + i."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Changing rates, two investments:","bold":true},{"text":" ₦100 now and ₦100 at time 3, accumulated to time 10."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"5% for 3 years, 6% for 3, 7% for 4: (100 × 1.05^3 + 100) × 1.06^3 × 1.07^4 = "},{"text":"₦336.84","bold":true},{"text":"."}]},{"text":[{"text":"6%, then 5%, then 7%: (100 × 1.06^3 + 100) × 1.05^3 × 1.07^4 = "},{"text":"₦332.47","bold":true},{"text":". Different, because the second ₦100 only meets the later rates."}]}]}]},{"text":[{"text":"Single sum:","bold":true},{"text":" ₦50,000 for 5 years at 5% for 2 years then 8% for 3: 50,000 × 1.05^2 = 55,125; × 1.08^3 = "},{"text":"₦69,441.62","bold":true},{"text":". Reversing the rates gives the same answer."}]},{"text":[{"text":"PV with changing rates:","bold":true},{"text":" ₦80,000 due at year 5; 10% for years 1 and 2, 9% for years 3 to 5. PV = 80,000/(1.1^2 × 1.09^3) = 80,000/1.566985 = "},{"text":"₦51,053.45","bold":true},{"text":"."}]},{"text":[{"text":"Loan cleared by a final payment:","bold":true},{"text":" Ngozi borrows ₦300,000 at 12%, repays ₦150,000 at the end of year 1. Balance after year 1: 336,000 − 150,000 = 186,000; final payment at year 3 = 186,000 × 1.12^2 = "},{"text":"₦233,318.40","bold":true},{"text":"."}]},{"text":[{"text":"Two equal repayments:","bold":true},{"text":" a ₦400,000 loan repaid by X at the end of years 1 and 2 at 8%: 400,000 = X(v + v^2) = X × 1.78326475, so X = "},{"text":"₦224,307.69","bold":true},{"text":"."}]},{"text":[{"text":"Equivalent single payment:","bold":true},{"text":" ₦40,000 due at year 1 and ₦90,000 at year 6; at 10%, the single payment at year 3 is 40,000 × 1.1^2 + 90,000 × 1.1^−3 = 48,400 + 67,618.33 = "},{"text":"₦116,018.33","bold":true},{"text":"."}]},{"text":[{"text":"Present value of several payments:","bold":true},{"text":" add each payment × v^n. At 10% half-yearly nominal, use 5% per half-year: ₦100,000 at year 1 and year 2 has PV 100,000(1.05^−2 + 1.05^−4) = 90,702.95 + 82,270.25 = "},{"text":"₦172,973.20","bold":true},{"text":"."}]},{"text":[{"text":"Rate, one payment:","bold":true},{"text":" ₦25,000 grows to ₦40,000 in 5 years. i = 1.6^(1/5) − 1 = "},{"text":"9.86%","bold":true},{"text":"."}]},{"text":[{"text":"Rate, quadratic:","bold":true},{"text":" ₦50,000 now and ₦50,000 in a year; the account holds ₦112,320 at the end of year 2. 50,000x^2 + 50,000x = 112,320, so x^2 + x − 2.2464 = 0. x = (−1 + √(1 + 8.9856))/2 = (−1 + 3.16)/2 = 1.08$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 24, $study_guide$, so "},{"text":"i = 8%","bold":true},{"text":"."}]},{"text":[{"text":"Time:","bold":true},{"text":" ₦60,000 to ₦100,000 at 7%: n = ln(5/3)/ln 1.07 = "},{"text":"7.55 years","bold":true},{"text":". Doubling at 8%: ln 2/ln 1.08 = 9.01 years; at δ = 8%: ln 2/0.08 = 8.66 years."}]},{"text":[{"text":"Trap:","bold":true},{"text":" never add payments at different dates at face value; move them to one date first."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"TVM: money now is worth more because it can earn interest; discounting finds present values."}]},{"text":[{"text":"Simple interest: A = P(1 + rt), the same interest each year; simple discount: P = A(1 − dt)."}]},{"text":[{"text":"Compound: AV = P(1 + i)^n; PV = FV v^n; v = 1/(1 + i) is the discount factor."}]},{"text":[{"text":"Under one year simple beats compound; at one year they are equal; beyond one year compound wins."}]},{"text":[{"text":"d = i/(1 + i) = iv = 1 − v; i = d/(1 − d)."}]},{"text":[{"text":"Nominal: 1 + i = (1 + i^(m)/m)^m; compare effective rates; 1 − d = (1 − d^(m)/m)^m."}]},{"text":[{"text":"Force: 1 + i = e^δ, δ = ln(1 + i), v = e^−δ; δ is the limit of i^(m)."}]},{"text":[{"text":"Ordering: d < d^(m) < δ < i^(m) < i."}]},{"text":[{"text":"Equations of value: value everything at one date; any date gives the same answer."}]},{"text":[{"text":"Time: n = ln(A/P)/ln(1 + i); rate: i = (A/P)^(1/n) − 1."}]}]}],"theory":{"itemId":"9a35d314-f734-5003-9bae-9f1da719e5c9","question":[{"type":"paragraph","text":[{"text":"A nominal rate of interest is 8% per annum convertible quarterly. Find (a) the equivalent effective annual rate of interest, (b) the force of interest, and (c) the accumulated value of ₦100,000 after 3 years. Give rates to 4 decimal places and money to the nearest kobo."}]}]},"practice":[{"topic":"Time Value of Money: Compound Interest and Discounting","named":false}]}},{"kind":"note","itemId":"9547b537-1d3f-5af0-b87f-dbac7dc05f27","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Present and Accumulated Values of Payment Streams","body":"The cash flows of common securities; present value and accumulated value of a stream of equal or unequal payments; moving a value to any date; equations of value (unknown payment, time or rate); changing rates of interest; net present value, internal rate of return (yield) and discounted payback.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"The cash flows of common securities; present value and accumulated value of a stream of equal or unequal payments; moving a value to any date; equations of value (unknown payment, time or rate); changing rates of interest; net present value, internal rate of return (yield) and discounted payback."}],"lessons":[{"number":"6.1","title":"Cash flows and the securities that produce them","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cash flow:","bold":true},{"text":" a payment (in or out) at a stated time. Valuing a contract means listing its cash flows and their times, then applying interest."}]},{"text":[{"text":"Bond:","bold":true},{"text":" a certificate of debt issued by a government or company, promising periodic interest payments and the return of the original amount on a stated date."}]},{"text":[{"text":"Coupon:","bold":true},{"text":" the interest payment on a bond. "},{"text":"Redemption:","bold":true},{"text":" the return of the investor's capital at the end."}]},{"text":[{"text":"Zero-coupon bond:","bold":true},{"text":" pays "},{"text":"no coupons","bold":true},{"text":"; makes a "},{"text":"single payment at maturity","bold":true},{"text":" whose money amount is known in advance."}]},{"text":[{"text":"Fixed-interest security:","bold":true},{"text":" pays regular "},{"text":"fixed coupons plus a redemption payment","bold":true},{"text":". Ignoring default, the money amounts and dates are fixed at issue. In actuarial and UK usage it is also called "},{"text":"loan stock","bold":true},{"text":" (or simply "},{"text":"stock","bold":true},{"text":"); a UK government bond is a "},{"text":"gilt","bold":true},{"text":". "},{"text":"Unsecured loan stock:","bold":true},{"text":" long-term company debt not secured on any specific assets."}]},{"text":[{"text":"Index-linked security:","bold":true},{"text":" coupons and redemption are "},{"text":"adjusted in line with an index","bold":true},{"text":" (usually inflation), so the money amounts are "},{"text":"not","bold":true},{"text":" known in advance; the dates are."}]},{"text":[{"text":"Call deposit:","bold":true},{"text":" money in a bank account that can be withdrawn on demand; the interest rate can change."}]},{"text":[{"text":"Equity (ordinary share):","bold":true},{"text":" pays dividends that depend on the company's profits and the directors' decisions; no redemption date."}]}]},{"type":"table","header":[[{"text":"Contract"}],[{"text":"Amount known in advance?"}],[{"text":"Timing known in advance?"}]],"rows":[[[{"text":"Zero-coupon bond"}],[{"text":"Yes"}],[{"text":"Yes"}]],[[{"text":"Fixed-interest security"}],[{"text":"Yes"}],[{"text":"Yes"}]],[[{"text":"Index-linked security"}],[{"text":"No"}],[{"text":"Yes"}]],[[{"text":"Call deposit"}],[{"text":"No"}],[{"text":"No"}]],[[{"text":"Equity"}],[{"text":"No"}],[{"text":"No"}]]]},{"type":"paragraph","text":[{"text":"Index-linked payment formula:","bold":true}]},{"type":"paragraph","text":[{"text":"Payment actually received = nominal payment × (index at payment date ÷ index at purchase date)"}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example.","italic":true},{"text":" An investor buys a two-year index-linked security on 1.1.2021. Without inflation it would pay ₦10,000 at the end of each year and ₦200,000 on redemption at 1.1.2023. Index: 1.1.2020 = 100; 1.1.2021 = 150; 1.1.2022 = 165; 1.1.2023 = 180."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Base is the index on the "},{"text":"purchase date","bold":true},{"text":", 150 (not 10$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 25, $study_guide$0)."}]},{"text":[{"text":"Payment on 1.1.2022 = 10,000 × 165/150 = "},{"text":"₦11,000","bold":true},{"text":"."}]},{"text":[{"text":"Payment on 1.1.2023 = 10,000 × 180/150 = "},{"text":"₦12,000","bold":true},{"text":"."}]},{"text":[{"text":"Redemption on 1.1.2023 = 200,000 × 180/150 = "},{"text":"₦240,000","bold":true},{"text":"."}]},{"text":[{"text":"If the index falls below the purchase value, the payment falls below the nominal amount (for example an index of 135 would give 10,000 × 135/150 = ₦9,000)."}]}]},{"type":"paragraph","text":[{"text":"Traps: a zero-coupon bond "},{"text":"does","bold":true},{"text":" pay something (once, at maturity); \"regular coupons plus redemption\" describes a fixed-interest security. For an equity, the dividend amount is never known in advance; dividends are usually paid at regular intervals but neither the date nor the amount is guaranteed. In Nigeria, FGN bonds are fixed-interest securities and Nigerian Treasury Bills work like zero-coupon instruments; pension funds supervised by PenCom and insurers supervised by NAICOM hold both."}]}]},{"number":"6.2","title":"Present value and accumulated value of a stream","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Present value (PV) of a payment stream:","bold":true},{"text":" the single value at time 0 found by discounting every payment to time 0 at a given rate of interest and adding the results."}]},{"text":[{"text":"Accumulated value (AV) at time n:","bold":true},{"text":" the total of all payments rolled forward with interest to time n."}]},{"text":[{"text":"Value at time t:","bold":true},{"text":" every payment is moved to time t (accumulated if it is earlier, discounted if it is later) and the results are added."}]}]},{"type":"paragraph","text":[{"text":"With payments C_1, C_2, ..., C_n at times t_1, t_2, ..., t_n and v = 1/(1 + i):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"PV = C_1 v^(t_1) + C_2 v^(t_2) + ... + C_n v^(t_n)"}]},{"text":[{"text":"AV at time n = sum of C_k (1 + i)^(n − t_k)"}]},{"text":[{"text":"Moving a value:","bold":true},{"text":" value at time t = PV × (1 + i)^t; PV = (value at time t) × v^t. So AV at n = PV × (1 + i)^n."}]},{"text":[{"text":"Times need not be whole numbers: v^0.5 = (1 + i)^(−0.5)."}]}]},{"type":"paragraph","text":[{"text":"Discount factor for each way of quoting interest:","bold":true}]},{"type":"table","header":[[{"text":"Basis given"}],[{"text":"Discount factor for time t"}]],"rows":[[[{"text":"Effective rate i per year"}],[{"text":"v^t = (1 + i)^(−t)"}]],[[{"text":"Nominal rate i^(m) convertible m-thly"}],[{"text":"(1 + i^(m)/m)^(−mt); use i^(m)/m per period and count periods"}]],[[{"text":"Force of interest δ"}],[{"text":"v^t = e^(−δt)"}]],[[{"text":"Effective rate of discount d"}],[{"text":"v = 1 − d, so v^t = (1 − d)^t"}]],[[{"text":"Simple interest at r"}],[{"text":"1/(1 + rt)"}]]]},{"type":"paragraph","text":[{"text":"Level payments","bold":true},{"text":" (from Topic 7, restated): ₦1 at the end of each year for n years has PV a_n| = (1 − v^n)/i and AV s_n| = ((1 + i)^n − 1)/i. Paid at the start of each year: ä_n| = (1 + i) a_n| and s̈_n| = (1 + i) s_n|."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (unequal payments).","italic":true},{"text":" ₦30,000 at time 1, ₦40,000 at time 2 and ₦50,000 at time 4, at 8% effective."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"PV = 30,000 × 1.08^(−1) + 40,000 × 1.08^(−2) + 50,000 × 1.08^(−4)"}]},{"text":[{"text":"= 27,777.78 + 34,293.55 + 36,751.49 = "},{"text":"₦98,822.82","bold":true}]},{"text":[{"text":"AV at time 4 = 30,000 × 1.08^3 + 40,000 × 1.08^2 + 50,000 = 37,791.36 + 46,656 + 50,000 = "},{"text":"₦134,447.36","bold":true}]},{"text":[{"text":"Check: 98,822.82 × 1.08^4 = ₦134,447.36."}]},{"text":[{"text":"Value at time 2 = 30,000 × 1.08 + 40,000 + 50,000 × 1.08^(−2) = 32,400 + 40,000 + 42,866.94 = "},{"text":"₦115,266.94","bold":true},{"text":" (also 98,822.82 × 1.08^2)."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2 (other bases).","italic":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Fractional time: ₦50,000 at time 0.5 at 10% effective: 50,000 × 1.1^(−0.5) = 50,000 × 0.953463 = "},{"text":"₦47,673","bold":true},{"text":" (nearest naira)."}]},{"text":[{"text":"Nominal rate: ₦20,000 at 6 months and ₦20,000 at 18 months, at 10% convertible half-yearly. Rate per half-year = 5%; the payments are 1 and 3 half-years away: 20,000/1.05 + 20,000/1.05^3 = 19,047.62 + 17,276.75 = "},{"text":"₦36,324.37","bold":true},{"text":"."}]},{"text":[{"text":"Force: ₦100,000 at time 2 with δ = 0.1: 100,000 × e^(−0.2) = "},{"text":"₦81,873","bold":true},{"text":" (nearest naira)."}]},{"text":[{"text":"Discount rate: ₦40,000 at times 1 and 2 with d = 10%: v = 0.9, PV = 40,000 × 0.9 + 40,000 × 0.81 = "},{"text":"₦68,400","bold":true},{"text":"."}]},{"text":[{"text":"Simple interest at 10%: ₦22,000 at time 1 and ₦24,000 at time 2: 22,000/1.1 + 24,000/1.2 = 20,000 + 20,000 = "},{"text":"₦40,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3 (level payments).","italic":true},{"text":" ₦10,000 at the end of each year for 5 years at 8%: a_5| = (1 − 1.08^(−5))/0.08 = 3.99271, so PV = "},{"text":"₦39,927","bold":true},{"text":"; s_5| = 5.86660, so AV at the time of the 5th payment = "},{"text":"₦58,666","bold":true},{"text":". Paid at the start of each year (times 0 to 4): PV = 39,927.10 × 1.08 = "},{"text":"₦43,121","bold":true},{"text":", and AV at time 5 = 58,666.01 × 1.08 = "},{"text":"₦63,359","bold":true},{"text":". If a question gives you a table value, such as a_4| = 3.2397 at 9%, simply multiply: ₦40,000 × 3.2397 = ₦129,588."}]},{"type":"paragraph","text":[{"text":"Worked example 4 (gaps and growth).","italic":true},{"text":" ₦10,000 at the ends of years 3, 4 and 5 only, at 8%: 10,000 × (1.08^(−3) + 1.08^(−4) + 1.08^(−5)) = "},{"text":"₦22,094","bold":true},{"text":", equal t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 26, $study_guide$o 10,000 × (a_5| − a_2|). A year with no payment simply contributes nothing. Payments of ₦50,000, ₦55,000 and ₦60,500 (growing 10% a year) at times 1, 2, 3 at 10%: each discounts to ₦45,454.55, so PV = "},{"text":"₦136,364","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Traps: the AV of an end-of-year series is measured \"at the time of the last payment\" (so the last payment earns no interest); for start-of-year deposits valued one year after the last deposit, every deposit earns interest. The PV is always less than the plain total of future positive payments, and the PV does "},{"text":"not","bold":true},{"text":" equal the AV at the last date (they differ by the factor (1 + i)^n)."}]}]},{"number":"6.3","title":"Equations of value","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Equation of value:","bold":true},{"text":" an equation stating that, at a chosen date (the "},{"text":"comparison date","bold":true},{"text":" or focal date), the total value of money paid out equals the total value of money received, at a given rate of interest."}]},{"text":[{"text":"General form: sum of (outgo values) = sum of (income values), all at the same date. At time 0: sum of C_t v^t = 0 with outflows negative."}]},{"text":[{"text":"Under "},{"text":"compound interest","bold":true},{"text":" any comparison date gives the "},{"text":"same answer","bold":true},{"text":", because moving from time 0 to time T multiplies every term by (1 + i)^T. Time 0 or the date of the unknown payment is usually easiest."}]},{"text":[{"text":"Uses: (1) find an unknown payment; (2) replace debts by one payment at a new date; (3) find an unknown time; (4) find an unknown rate (yield); (5) loan repayments and saving targets."}]},{"text":[{"text":"Equal loan repayment: loan = R × a_n|, so R = loan ÷ a_n|. Saving target: target = D × s_n| (end of year) or D × s̈_n| (start of year)."}]},{"text":[{"text":"Unknown time: rearrange to (1 + i)^t = k, then t = ln k ÷ ln(1 + i)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Replacing debts.","italic":true},{"text":" Debts of ₦80,000 due at time 1 and ₦120,000 due at time 4 are replaced by one payment at time 2, at 10%. At time 2: X = 80,000 × 1.1 + 120,000 × 1.1^(−2) = 88,000 + 99,173.55 = "},{"text":"₦187,174","bold":true},{"text":" (nearest naira). The earlier debt is accumulated, the later one discounted. A Kano debtor and creditor are equally well off because both sides are valued at the same date and rate."}]},{"type":"paragraph","text":[{"text":"Unknown final payment.","italic":true},{"text":" A loan of ₦300,000 is repaid by ₦100,000 at time 1 and X at time 2, at 12%. At time 2: 300,000 × 1.12^2 = 100,000 × 1.12 + X, so X = 376,320 − 112,000 = "},{"text":"₦264,320","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Payments in a ratio.","italic":true},{"text":" A loan of ₦300,000 is repaid by X at time 1 and 2X at time 3, at 8%: 300,000 = X(1.08^(−1) + 2 × 1.08^(−3)) = X × 2.513590, so X = "},{"text":"₦119,351","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Two equal payments.","italic":true},{"text":" A debt of ₦400,000 due at time 3 is replaced by X at time 1 and X at time 5, at 10%: X(1.1^(−1) + 1.1^(−5)) = 400,000 × 1.1^(−3), so X × 1.530012 = 300,525.92 and X = "},{"text":"₦196,421","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Loan and saving.","italic":true},{"text":" ₦500,000 borrowed, repaid by 4 equal year-end payments at 10%: R = 500,000 ÷ 3.169865 = "},{"text":"₦157,735","bold":true},{"text":". To have ₦600,000 at time 5 by 5 equal deposits at 7%: end of each year, D = 600,000 ÷ s_5| = 600,000 ÷ 5.750739 = "},{"text":"₦104,334","bold":true},{"text":"; start of each year, D = 600,000 ÷ 6.153291 = "},{"text":"₦97,509","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Unknown time (equated time).","italic":true},{"text":" ₦60,000 due at time 1 and ₦60,000 at time 5 are replaced by ₦120,000 at time t, at 6%:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"120,000 v^t = 60,000(v + v^5), so v^t = (0.943396 + 0.747258)/2 = 0.845327"}]},{"text":[{"text":"(1.06)^t = 1.182974, t = ln 1.182974 ÷ ln 1.06 = 0.168032 ÷ 0.058269 = "},{"text":"2.88 years","bold":true},{"text":" (2 d.p.), earlier than the simple average of 3 years."}]}]},{"type":"paragraph","text":[{"text":"Time to reach a target.","italic":true},{"text":" ₦50,000 now and ₦50,000 at time 1, at 10%: when is the fund ₦150,000? 50,000(1.1)^t + 50,000(1.1)^(t − 1) = 150,000, so (1.1)^t × (1 + 1/1.1) = 3, (1.1)^t = 1.571429, t = 0.451985 ÷ 0.095310 = "},{"text":"4.74 years","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Unknown rate.","italic":true},{"text":" ₦100,000 deposited at times 0 and 1 gives ₦231,000 at time 2. Let x = 1 + i: 100,000x^2 + 100,000x = 231,000, so x^2 + x − 2.31 = 0, x = (−1 + √10.24)/2 = (−1 + 3.2)/2 = 1.1, so "},{"text":"i = 10%","bold":true},{"text":". With answer options, you can also test each rate."}]}]},{"number":"6.4","title":"Changing rates and sensitivity to the rate","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"When the rate changes over time, accumulate (or discount) "},{"text":"period by period","bold":true},{"text":", using the rate in force in each period: AV of ₦1 over two years at i_1 then i_2 = (1 + i_1)(1 + i_2)."}]},{"text":[{"text":"Discount factor to time 2 when year 1 is at i_1 and year 2 at i_2: 1/[(1 + i_1)(1 + i_2)]."}]},{"text":[{"text":"A later deposit earns only the rates that apply "},{"text":"after","bold":true},{"text":" it is made."}]},{"text":[{"text":"Higher rate, lower PV:","bold":true},{"text":" each v^t gets smaller, so the PV of fixed positive future payments "},{"text":"falls","bold":true},{"text":" when i rises (and the AV rises)."}]},{"text":[{"text":"Payments due "},{"text":"later","bold":true},{"text":" are hit harder: long-dated streams lose more value than short-dated ones when rat$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 27, $study_guide$es rise."}]},{"text":[{"text":"A naira due later adds less to the PV than a naira due sooner."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Changing rates, accumulation.","italic":true},{"text":" ₦100 for ten years at 5% for 3 years, 6% for 3 years and 7% for 4 years: 100 × 1.05^3 × 1.06^3 × 1.07^4 = "},{"text":"₦180.73","bold":true},{"text":". With a second deposit: ₦200,000 now and ₦100,000 at time 2; 6% for years 1-2, then 9% for years 3-5. Value at time 2 = 200,000 × 1.06^2 + 100,000 = 224,720 + 100,000 = 324,720. At time 5: 324,720 × 1.09^3 = 324,720 × 1.295029 = "},{"text":"₦420,522","bold":true},{"text":". Order matters: swapping which rate applies first changes the answer when deposits are made in between."}]},{"type":"paragraph","text":[{"text":"Changing rates, discounting.","italic":true},{"text":" 10% in year 1 and 12% in year 2; ₦100,000 at times 1 and 2: PV = 100,000/1.1 + 100,000/(1.1 × 1.12) = 90,909.09 + 81,168.83 = "},{"text":"₦172,078","bold":true},{"text":" (nearest naira). Do "},{"text":"not","bold":true},{"text":" discount the second payment at 1.12^2."}]},{"type":"paragraph","text":[{"text":"Withdrawals.","italic":true},{"text":" ₦100,000 deposited now, ₦30,000 withdrawn at time 2, 9%: balance at time 4 = 100,000 × 1.09^4 − 30,000 × 1.09^2 = "},{"text":"₦105,515","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Choice depends on the rate.","italic":true},{"text":" ₦100,000 at time 1 against ₦130,000 at time 4:"}]},{"type":"table","header":[[{"text":"Rate"}],[{"text":"PV of ₦100,000 at time 1"}],[{"text":"PV of ₦130,000 at time 4"}],[{"text":"Better"}]],"rows":[[[{"text":"5%"}],[{"text":"₦95,238"}],[{"text":"₦106,951"}],[{"text":"later sum"}]],[[{"text":"10%"}],[{"text":"₦90,909"}],[{"text":"₦88,792"}],[{"text":"earlier sum"}]]]},{"type":"paragraph","text":[{"text":"Sensitivity.","italic":true},{"text":" ₦100,000 at the end of each of 3 years: PV is 100,000 a_3| = ₦267,301 at 6% but ₦240,183 at 12%, a fall of ₦27,118. Two streams equal in value at one rate are no longer equal at a higher rate: the one paying mostly later now has the "},{"text":"lower","bold":true},{"text":" PV. Comparing values at a later date: if two streams have PVs of P_1 and P_2, their values at time t differ by (P_1 − P_2)(1 + i)^t."}]}]},{"number":"6.5","title":"Net present value, internal rate of return and payback","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Net present value (NPV):","bold":true},{"text":" PV of inflows minus PV of outflows at a chosen rate: NPV = C_0 + C_1 v + C_2 v^2 + ... + C_n v^n, outflows negative."}]},{"text":[{"text":"Decision rule:","bold":true},{"text":" NPV > 0, accept (it earns more than the required rate); NPV < 0, reject (it earns less than the required rate); NPV = 0, it earns exactly that rate."}]},{"text":[{"text":"Internal rate of return (IRR), or yield:","bold":true},{"text":" the discount rate at which NPV = 0 (the equation of value is satisfied). For a bond, the yield to redemption (redemption yield) is the IRR of buying it."}]},{"text":[{"text":"Hurdle rate:","bold":true},{"text":" the minimum IRR required on a project to compensate for its risk. Accept if IRR exceeds the hurdle rate."}]},{"text":[{"text":"If NPV is positive at i_1 and negative at i_2, the IRR lies "},{"text":"between","bold":true},{"text":" i_1 and i_2. Estimate by linear interpolation: IRR ≈ i_1 + (i_2 − i_1) × NPV_1 ÷ (NPV_1 − NPV_2)."}]},{"text":[{"text":"Payback period:","bold":true},{"text":" time needed to recover the cost from undiscounted cash flows; it ignores the time value of money."}]},{"text":[{"text":"Discounted payback period:","bold":true},{"text":" the number of years needed to recover the initial outlay after each cash flow has been discounted; the first year in which the cumulative discounted cash flow becomes positive."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"NPV.","italic":true},{"text":" A Lagos firm considers a machine costing ₦800,000 that returns ₦300,000 at the end of each of 3 years. At 10%: NPV = −800,000 + 300,000 × a_3| = −800,000 + 300,000 × 2.486852 = "},{"text":"−₦53,944","bold":true},{"text":". Reject: the project earns less than 10%, even though plain inflows (₦900,000) exceed the cost. With mixed flows, for example −₦300,000 at time 0 and −₦100,000 at time 1, discount every outflow too; an outflow at time 1 becomes −100,000/1.1."}]},{"type":"paragraph","text":[{"text":"IRR by quadratic.","italic":true},{"text":" A project costs ₦100,000 and returns ₦60,000 at time 1 and ₦72,000 at time 2. NPV = 0 gives 72,000v^2 + 60,000v − 100,000 = 0. Divide by 4,000: 18v^2 + 15v − 25 = 0. v = (−15 + √(225 + 1,800))/36 = (−15 + 45)/36 = 0.833333 (take the positive root). i = 1/v − 1 = "},{"text":"20%","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"IRR by testing options.","italic":true},{"text":" If ₦100,000 now buys ₦55,000 at time 1 and ₦60,500 at time 2, test 10%: 55,000/1.1 + 60,500/1.21 = 50,000 + 50,000 = 100,000. NPV = 0, so the IRR is "},{"text":"10%","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"IRR by bracketing.","italic":true},{"text":" Cost ₦400,000; returns ₦150,000, ₦200,000 and ₦120,000 at times 1, 2, 3. NPV at 8% = +₦5,617; at 10% = −₦8,189. So the IRR lies between 8% and 10%. Interpolation: 8% + 2% × 5,617/(5,617 + 8,189) = "},{"text":"8.81%","bold":true},{"text":" (true value 8.80%)."}]},{"type":"paragraph","text":[{"text":"Discounted payback.","italic":true},{"text":" Cost ₦600,000; ₦250,000 at the end of each year; 12%."}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Discounted inflow"}],[{"text":"Cumulative"}]],"rows":[[[{"text":"1"}],[{"text":"223,214"}],[{"text":"−376,786"}]],[[{"text":"2"}],[{"text":"199,298"}],[{"text":"−177,487"}]],[[{"text":"3"}],[{"text":"177,945"}],[{"text":"+458"}]]]},{"type":"paragraph","text":[{"text":"Discounted payback = "},{"text":"year 3","bold":true},{"text":" (first positive cumulative). The o$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 28, $study_guide$rdinary payback is 600,000/250,000 = 2.4 years, shorter, because it ignores interest."}]},{"type":"paragraph","text":[{"text":"Largest loan.","italic":true},{"text":" A Nigerian microfinance bank charging 18% will lend at most the PV of what the borrower can repay. A borrower who can pay ₦100,000 at each of times 1 and 2 can be lent 100,000 × (1.18^(−1) + 1.18^(−2)) = "},{"text":"₦156,564","bold":true},{"text":" (nearest naira)."}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Zero-coupon: one known payment at maturity. Fixed-interest (loan stock): known coupons plus redemption. Index-linked: amounts move with an index (base = index at purchase)."}]},{"text":[{"text":"PV = sum of C_t v^t; AV at n = sum of C_t (1 + i)^(n − t); value at t = PV × (1 + i)^t."}]},{"text":[{"text":"Convert the rate to the payment period, or use e^(−δt), (1 − d)^t or 1/(1 + rt) as given."}]},{"text":[{"text":"Equation of value: outgo = income at one date; under compound interest any date gives the same answer."}]},{"text":[{"text":"Solve for X directly, for t with logs, for i by quadratic or by testing options."}]},{"text":[{"text":"Changing rates: multiply period by period; later deposits earn only later rates."}]},{"text":[{"text":"Higher rate, lower PV; long-dated streams fall most."}]},{"text":[{"text":"NPV > 0 accept; IRR = yield = rate making NPV zero; NPV changing sign brackets the IRR."}]},{"text":[{"text":"Discounted payback: first year cumulative discounted cash flow is positive."}]}]}],"theory":{"itemId":"9183b89f-38d6-54e3-a6cf-d7d739aac07b","question":[{"type":"paragraph","text":[{"text":"A debt of ₦200,000 is due at time 3. It is to be settled by X at time 1 and X at time 2. At 10% per annum effective, find X."}]}]},"practice":[{"topic":"Present and Accumulated Values of Payment Streams","named":false}]}},{"kind":"note","itemId":"76212540-e7ee-5580-b2e3-490e47a81996","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Annuities and Annuity Functions","body":"The types of annuity and their symbols; a_n|, s_n|, ä_n|, s̈_n| and how they are linked; loans and savings funds; deferred annuities and perpetuities; m-thly and continuous annuities; increasing, decreasing and geometric annuities.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"The types of annuity and their symbols; a_n|, s_n|, ä_n|, s̈_n| and how they are linked; loans and savings funds; deferred annuities and perpetuities; m-thly and continuous annuities; increasing, decreasing and geometric annuities."}],"lessons":[{"number":"7.1","title":"Types of annuity and their symbols","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Annuity:","bold":true},{"text":" a series of payments made at regular intervals of time. As a contract, an annuity is an agreement with an insurance company that provides a series of payments at regular intervals for a number of years or over a lifetime."}]},{"text":[{"text":"Annuity-immediate:","bold":true},{"text":" payments at the "},{"text":"end","bold":true},{"text":" of each period (times 1, 2, ..., n). Also called an "},{"text":"ordinary annuity","bold":true},{"text":" or an "},{"text":"annuity in arrears","bold":true},{"text":"."}]},{"text":[{"text":"Annuity-due:","bold":true},{"text":" payments at the "},{"text":"start","bold":true},{"text":" of each period (times 0, 1, ..., n - 1). Also called an "},{"text":"annuity in advance","bold":true},{"text":"."}]},{"text":[{"text":"Deferred annuity:","bold":true},{"text":" payments do not begin immediately, or in the first period, but only after a period of postponement. Deferred m periods: payments at times m + 1, ..., m + n."}]},{"text":[{"text":"Perpetuity:","bold":true},{"text":" an annuity payable for an unlimited term; payments continue for ever, with no termination date."}]},{"text":[{"text":"Annuity-certain:","bold":true},{"text":" pays for a fixed term whatever happens."}]},{"text":[{"text":"Life (contingent) annuity:","bold":true},{"text":" pays only while a named life survives."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Whole-life annuity:","bold":true},{"text":" pays for as long as the person lives; payments stop at death."}]},{"text":[{"text":"Temporary life annuity for n years:","bold":true},{"text":" continues during the joint duration of the life of (x) and a term of n years certain, so it stops at death or after n years, whichever comes first."}]},{"text":[{"text":"Reversionary annuity:","bold":true},{"text":" an annuity on the life of (x) after the death of (y)."}]}]}]}]},{"type":"paragraph","text":[{"text":"The symbols (International Actuarial Notation)","bold":true}]},{"type":"table","header":[[{"text":"Symbol"}],[{"text":"Meaning"}]],"rows":[[[{"text":"a_n|"}],[{"text":"present value of an annuity-immediate of 1 per period for n periods"}]],[[{"text":"s_n|"}],[{"text":"accumulated value (amount) at time n of that annuity-immediate"}]],[[{"text":"ä_n| (a-double-dot)"}],[{"text":"present value of an annuity-due"}]],[[{"text":"s̈_n| (s-double-dot)"}],[{"text":"accumulated value at time n of an annuity-due"}]],[[{"text":"ā_n| (a-bar)"}],[{"text":"present value of a continuous annuity (payable continuously)"}]],[[{"text":"m|a_n|"}],[{"text":"present value of an annuity deferred m periods"}]],[[{"text":"a_∞| , ä_∞|"}],[{"text":"perpetuity-immediate, perpetuity-due"}]],[[{"text":"a^(m)_n| , ä^(m)_n|"}],[{"text":"annuity of 1 per period paid m-thly, in arrears or in advance"}]],[[{"text":"(Ia)_n| , (Da)_n| , (va)"}],[{"text":"increasing, decreasing and varying annuities"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"a","bold":true},{"text":" = present value of an annuity; "},{"text":"s","bold":true},{"text":" = amount of an annuity; "},{"text":"A","bold":true},{"text":" = present value of an assurance (not an annuity)."}]},{"text":[{"text":"The "},{"text":"diaeresis","bold":true},{"text":" (two dots) over a or s is the symbol of "},{"text":"acceler$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 29, $study_guide$ation of payments","bold":true},{"text":": payments at the beginning of each period."}]},{"text":[{"text":"A "},{"text":"bar","bold":true},{"text":" over the principal symbol means "},{"text":"continuous","bold":true},{"text":" (momently) payment."}]},{"text":[{"text":"Sometimes the rate is shown as a subscript: a_n|i."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"annuity-due\" is the odd one out. Annuity in arrears, ordinary annuity and annuity-immediate all mean end-of-period payments."}]},{"text":[{"text":"A tenant in Yaba paying rent of ₦400,000 at the beginning of each year for 3 years, starting today, is a 3-year annuity-due from the landlord's side."}]},{"text":[{"text":"Preference shares paying a fixed dividend every year with no redemption date are valued as a "},{"text":"perpetuity","bold":true},{"text":"."}]},{"text":[{"text":"A retiree's pension of ₦150,000 every month until death is a "},{"text":"whole-life (contingent) annuity","bold":true},{"text":". Under the Nigerian Contributory Pension Scheme, regulated by PenCom, a retiree can use the balance in a Retirement Savings Account to buy a life annuity from a life insurer."}]}]}]},{"number":"7.2","title":"Annuity-immediate: a_n| and s_n|","mustKnow":[{"type":"paragraph","text":[{"text":"With v = 1/(1 + i):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"a_n| = v + v^2 + ... + v^n = (1 - v^n)/i = [1 - (1 + i)^-n]/i"}]},{"text":[{"text":"s_n| = (1 + i)^(n-1) + ... + (1 + i) + 1 = [(1 + i)^n - 1]/i"}]},{"text":[{"text":"s_n| = (1 + i)^n × a_n|"}]},{"text":[{"text":"Level payment P: PV = P × a_n|, FV (future value) = P × s_n| = P[(1 + i)^n - 1]/i."}]},{"text":[{"text":"Loan instalment","bold":true},{"text":" (first payment one period after the loan): X = Loan / a_n|."}]},{"text":[{"text":"Savings (sinking) fund","bold":true},{"text":" target F, deposits in arrears: X = F / s_n|."}]},{"text":[{"text":"Value at time t","bold":true},{"text":" (0 ≤ t ≤ n, just after the t-th payment) = s_t| + a_(n-t)| = (1 + i)^t a_n|."}]},{"text":[{"text":"Outstanding loan","bold":true},{"text":" just after the t-th instalment = X × a_(n-t)| (PV of the remaining instalments)."}]},{"text":[{"text":"Total interest","bold":true},{"text":" on a loan = n × X - Loan."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1 (PV and FV).","bold":true},{"text":" ₦100,000 at the end of each year for 5 years at 9%."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"v^5 = 1.09^-5 = 0.649931, so a_5| = (1 - 0.649931)/0.09 = 3.8897 (4 d.p.)."}]},{"text":[{"text":"PV = 100,000 × 3.889651 = "},{"text":"₦388,965","bold":true},{"text":"."}]},{"text":[{"text":"s_5| = (1.538624 - 1)/0.09 = 5.9847; FV = "},{"text":"₦598,471","bold":true},{"text":". Check: 388,965 × 1.09^5 = 598,471."}]}]},{"type":"paragraph","text":[{"text":"Example 2 (loan).","bold":true},{"text":" A loan of ₦2,000,000 is repaid by 4 equal annual instalments in arrears at 12%."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"a_4| = (1 - 1.12^-4)/0.12 = (1 - 0.635518)/0.12 = 3.0373."}]},{"text":[{"text":"X = 2,000,000/3.037349 = "},{"text":"₦658,469","bold":true},{"text":"."}]},{"text":[{"text":"Just after the 1st instalment, the outstanding loan = X × a_3| = 658,468.87 × 2.401831 = "},{"text":"₦1,581,531","bold":true},{"text":"."}]},{"text":[{"text":"Total interest = 4 × 658,468.87 - 2,000,000 = "},{"text":"₦633,875","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Example 3 (savings fund).","bold":true},{"text":" A firm wants ₦1,000,000 in 6 years, depositing at the end of each year at 8%. s_6| = (1.586874 - 1)/0.08 = 7.3359. Deposit = 1,000,000/7.335929 = "},{"text":"₦136,315","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 4 (how many payments).","bold":true},{"text":" ₦300,000 pays ₦40,000 at the end of each year for as long as possible at 6%. Need a_n| = 300,000/40,000 = 7.5. At 6%, a_10| = 7.3601 and a_11| = 7.8869, so "},{"text":"10 full payments","bold":true},{"text":" (a_11| is too big). The fund left at time 0 is 300,000 - 40,000 × 7.360087 = 5,596.52; at time 10 this is 5,596.52 × 1.06^10 = 5,596.52 × 1.790848 = "},{"text":"₦10,023","bold":true},{"text":", the extra amount paid with the 10th payment."}]},{"type":"paragraph","text":[{"text":"Example 5 (finding the rate).","bold":true},{"text":" a_10| = 7.3601 at some rate. Try values: at 6%, a_10| = 7.3601. So i = "},{"text":"6%","bold":true},{"text":". In a CBT, test each option in (1 - (1 + i)^-n)/i; a higher rate gives a smaller a_n|."}]},{"type":"paragraph","text":[{"text":"Example 6 (value at an intermediate time).","bold":true},{"text":" A 5-year annuity-immediate of 1 at 9%, valued just after the 2nd payment: s_2| + a_3| = 2.0900 + 2.5313 = "},{"text":"4.6213","bold":true},{"text":" (equal to 1.09^2 × 3.889651)."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"If a_n| is given, v^n = 1 - i × a_n|, and s_n| = (1 + i)^n × a_n| = a_n|/v^n. Example: a_n| = 10.5631 at 4% gives v^n = 1 - 0.04 × 10.5631 = 0.5775."}]},{"text":[{"text":"If only v is given, a_n| = v + v^2 + ... + v^n. With v = 0.95: a_4| = 0.95 + 0.9025 + 0.857375 + 0.814506 = "},{"text":"3.5244","bold":true},{"text":"."}]},{"text":[{"text":"Trap: [1 - (1 + i)^-n]/i is a PV; [(1 + i)^n - 1]/i is an FV. Expressions with (1 + i)^n in place of (1 + i)^-n in a PV are wrong."}]}]}]},{"number":"7.3","title":"Annuity-due and the key relationships","mustKnow":[{"type":"paragraph","text":[{"text":"With d = i/(1 + i) = 1 - v:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"ä_n| = 1 + v + ... + v^(n-1) = (1 - v^n)/d"}]},{"text":[{"text":"s̈_n| = [(1 + i)^n - 1]/d = (1 + i)^n × ä_n|"}]},{"text":[{"text":"ä_n| = (1 + i) × a_n|  and  s̈_n| = (1 + i) × s_n| (each payment is one period earlier)"}]},{"text":[{"text":"ä_n| = 1 + a_(n-1)| (a payment now plus an (n - 1)-payment annuity-immediate)"}]},{"text":[{"text":"s_(n+1)| = s̈_n| + 1$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 30, $study_guide$ (an n-payment annuity-due from time 1 plus a final 1 at time n + 1)"}]},{"text":[{"text":"ä_n| - a_n| = 1 - v^n"}]},{"text":[{"text":"Splitting a term:","bold":true},{"text":" a_(m+n)| = a_m| + v^m a_n|;  s_(m+n)| = (1 + i)^n s_m| + s_n|."}]},{"text":[{"text":"For a positive rate, "},{"text":"ä_n| > a_n|","bold":true},{"text":" because each payment is received one period earlier; likewise s̈_n| > s_n|."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1.","bold":true},{"text":" At 5%, a_5| = 4.3295, so ä_6| = 1 + a_5| = "},{"text":"5.3295","bold":true},{"text":". Check: (1 - 1.05^-6)/d with d = 0.05/1.05 = 0.047619 gives 5.3295."}]},{"type":"paragraph","text":[{"text":"Example 2.","bold":true},{"text":" At 5%, s̈_6| = (1.340096 - 1)/0.047619 = 7.1420, so s_7| = s̈_6| + 1 = "},{"text":"8.1420","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 3 (rent in advance).","bold":true},{"text":" A shop is let for 6 years at ₦250,000 at the beginning of each year, 5%. PV = 250,000 × 5.329477 = "},{"text":"₦1,332,369","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 4 (d given).","bold":true},{"text":" d = 5%, so v = 0.95. ä_4| = (1 - 0.95^4)/0.05 = (1 - 0.814506)/0.05 = "},{"text":"3.7099","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 5 (lease or deposit in advance).","bold":true},{"text":" Equal instalments at the start of each year: X = PV / ä_n|. A fund target F with deposits at the start of each year: X = F / s̈_n|, where s̈_n| measures the balance at time n, one year after the last deposit."}]},{"type":"paragraph","text":[{"text":"Example 6 (splitting).","bold":true},{"text":" At 10%, a_2| = 1.7355, a_3| = 2.4869, v^2 = 0.826446: a_5| = a_2| + v^2 a_3| = 1.7355 + 0.826446 × 2.4869 = "},{"text":"3.7908","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps: s̈_n| = s_n|/(1 + i) is "},{"text":"wrong","bold":true},{"text":" (it is multiplied, not divided). ä_n| = 1 + a_n| is wrong (it is 1 + a_(n-1)|). a_(m+n)| = a_m| + a_n| is wrong (the second block must be discounted by v^m)."}]},{"text":[{"text":"Difference between due and immediate for ₦100,000 a year for 5 years at 10%: 100,000 × (1 - 1.1^-5) = 100,000 × 0.379079 = "},{"text":"₦37,908","bold":true},{"text":"."}]}]}]},{"number":"7.4","title":"Deferred annuities and perpetuities","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Deferred annuity-immediate","bold":true},{"text":" (payments at m + 1, ..., m + n):"}],"blocks":[{"type":"paragraph","text":[{"text":"m|a_n| = v^m a_n| = a_(m+n)| - a_m| = (v^m - v^(m+n))/i."}]}]},{"text":[{"text":"Deferred annuity-due","bold":true},{"text":" (payments at m, ..., m + n - 1): m|ä_n| = v^m ä_n|."}]},{"text":[{"text":"If the first payment is at time k (in arrears), the deferment is m = k - 1."}]},{"text":[{"text":"Perpetuity-immediate:","bold":true},{"text":" a_∞| = 1/i. Reason: v < 1, so v^n tends to 0 as n tends to infinity in a_n| = (1 - v^n)/i."}]},{"text":[{"text":"Perpetuity-due:","bold":true},{"text":" ä_∞| = 1/d = (1 + i)/i = 1 + 1/i."}]},{"text":[{"text":"Deferred perpetuity","bold":true},{"text":" (first payment at time m + 1): v^m/i."}]},{"text":[{"text":"Payments from time n + 1 onwards: 1/i - a_n| = v^n/i."}]},{"text":[{"text":"Rate from a perpetuity:","bold":true},{"text":" i = payment / price (in arrears). If in advance, price = X + X/i, so i = X/(price - X)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1.","bold":true},{"text":" 2|a_3| at 10% (payments at times 3, 4, 5): v^2 a_3| = 0.826446 × 2.4869 = "},{"text":"2.0552","bold":true},{"text":". Check: a_5| - a_2| = 3.7908 - 1.7355 = 2.0553 (difference from rounding; 2.0552 to 4 d.p.)."}]},{"type":"paragraph","text":[{"text":"Example 2 (gift).","bold":true},{"text":" ₦100,000 at the end of each year for 3 years, the first at the end of year 3, at 10%: deferment m = 2, PV = 100,000 × 2.055250 = "},{"text":"₦205,525","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 3 (perpetuities at 12%, ₦90,000 a year).","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"In arrears: 90,000/0.12 = "},{"text":"₦750,000","bold":true},{"text":"."}]},{"text":[{"text":"In advance (first payment today): 90,000 × 1.12/0.12 = "},{"text":"₦840,000","bold":true},{"text":"."}]},{"text":[{"text":"First payment at the end of year 5 (m = 4): 750,000 × 1.12^-4 = 750,000 × 0.635518 = "},{"text":"₦476,639","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Example 4 (rate).","bold":true},{"text":" ₦600,000 buys ₦45,000 a year in arrears for ever: i = 45,000/600,000 = "},{"text":"7.5%","bold":true},{"text":". ₦1,500,000 buys ₦100,000 a year with the first payment today: i = 100,000/1,400,000 = "},{"text":"7.14%","bold":true},{"text":" (2 d.p.)."}]},{"type":"paragraph","text":[{"text":"Example 5.","bold":true},{"text":" At 10%, payments of 1 from year 9 onwards: 1/0.1 - a_8| = 10 - 5.3349 = "},{"text":"4.6651","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"If d is given, perpetuity-due = 1/d and perpetuity-immediate = 1/i = 1/d - 1. With d = 0.04: 25 and 24."}]},{"text":[{"text":"Trap: a_(m+n)| + a_m| is "},{"text":"not","bold":true},{"text":" a deferred annuity value; the correct form subtracts."}]}]}]},{"number":"7.5","title":"Annuities payable m-thly and continuously","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Payment period = interest period:","bold":true},{"text":" use the rate per payment period and the number of payments. 24% convertible monthly gives 2% a month."}]},{"text":[{"text":"Periods differ:","bold":true},{"text":" first find the "},{"text":"effective rate j per payment period","bold":true},{"text":", then use a_n|j."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Payments less often than interest (e.g. half-yearly payments, interest quarterly$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 31, $study_guide$): j = (1 + i^(4)/4)^2 - 1."}]},{"text":[{"text":"Payments more often than interest (e.g. quarterly payments, interest half-yearly): j = (1 + i^(2)/2)^(1/2) - 1."}]}]}]},{"text":[{"text":"m-thly formulae","bold":true},{"text":" (1/m paid every 1/m of a year, total 1 a year, i effective annual):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"a^(m)_n| = (1 - v^n)/i^(m), where i^(m) = m[(1 + i)^(1/m) - 1]"}]},{"text":[{"text":"ä^(m)_n| = (1 - v^n)/d^(m), where d^(m) = m[1 - (1 + i)^(-1/m)]"}]},{"text":[{"text":"s^(m)_n| = [(1 + i)^n - 1]/i^(m); a^(m)_n| = (i/i^(m)) a_n|."}]}]}]},{"text":[{"text":"Continuous annuity:","bold":true},{"text":" ā_n| = (1 - v^n)/δ, with δ = ln(1 + i)."}]},{"text":[{"text":"Order for the same i > 0 and 1 a year: a_n| < a^(m)_n| < ā_n| < ä^(m)_n| < ä_n|."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1 (monthly).","bold":true},{"text":" ₦8,000 at the end of each month for 2 years at 12% convertible monthly. j = 1% a month, 24 payments: a_24| = (1 - 1.01^-24)/0.01 = 21.2434. PV = "},{"text":"₦169,947","bold":true},{"text":". Monthly loan instalments work the same way: X = Loan / a_(12n)| at the monthly rate."}]},{"type":"paragraph","text":[{"text":"Example 2 (payments less often).","bold":true},{"text":" ₦50,000 at the end of each half-year for 3 years at 12% convertible monthly. j = 1.01^6 - 1 = 0.061520 per half-year. PV = 50,000 × a_6|j = 50,000 × 4.8939 = "},{"text":"₦244,696","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 3 (payments more often).","bold":true},{"text":" ₦30,000 at the end of each quarter for 2 years at 12% convertible half-yearly. j = 1.06^(1/2) - 1 = 0.029563 per quarter. PV = 30,000 × a_8|j = 30,000 × 7.0327 = "},{"text":"₦210,980","bold":true},{"text":" (to the nearest naira, using unrounded factors)."}]},{"type":"paragraph","text":[{"text":"Example 4 (formula).","bold":true},{"text":" ₦60,000 a year paid as ₦5,000 at the end of each month for 5 years, 8% effective. i^(12) = 12(1.08^(1/12) - 1) = 0.077208; 1 - v^5 = 0.319417. a^(12)_5| = 0.319417/0.077208 = 4.1371. PV = 60,000 × 4.137075 = "},{"text":"₦248,225","bold":true},{"text":". Paid at the "},{"text":"start","bold":true},{"text":" of each month: d^(12) = 12(1 - 1.08^(-1/12)) = 0.076715, ä^(12)_5| = 4.1637, PV = "},{"text":"₦249,822","bold":true},{"text":". Note: multiply by the "},{"text":"annual","bold":true},{"text":" amount."}]},{"type":"paragraph","text":[{"text":"Example 5 (continuous).","bold":true},{"text":" ā_5| at 8%: δ = ln 1.08 = 0.076961, ā_5| = 0.319417/0.076961 = "},{"text":"4.1504","bold":true},{"text":". It lies between a_5| = 3.9927 and ä_5| = 4.3121."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: a^(m)_n| uses v^n (years) on top, not v^(mn), and i^(m) underneath, not i."}]}]}]},{"number":"7.6","title":"Increasing, decreasing, geometric and simple-interest annuities","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Increasing annuity-immediate","bold":true},{"text":" (1 at time 1, 2 at time 2, ..., n at time n):"}],"blocks":[{"type":"paragraph","text":[{"text":"(Ia)_n| = (ä_n| - n v^n)/i.  Increasing annuity-due: (Iä)_n| = (1 + i)(Ia)_n|."}]}]},{"text":[{"text":"Decreasing annuity-immediate","bold":true},{"text":" (n at time 1, n - 1 at time 2, ..., 1 at time n):"}],"blocks":[{"type":"paragraph","text":[{"text":"(Da)_n| = (n - a_n|)/i."}]}]},{"text":[{"text":"Arithmetic","bold":true},{"text":" (P at time 1, rising by D each period): PV = P a_n| + D(a_n| - n v^n)/i."}]},{"text":[{"text":"Geometric","bold":true},{"text":" (1 at time 1, rising by k each period, k ≠ i): PV = [1 - ((1 + k)/(1 + i))^n]/(i - k). Multiply by the first payment."}]},{"text":[{"text":"Varying annuity","bold":true},{"text":" (va): payments of any amounts; value each payment separately."}]},{"text":[{"text":"Simple interest:","bold":true},{"text":" PV of 1 due at t is 1/(1 + rt), so a_n| = sum of 1/(1 + rt) for t = 1 to n. There is no neat formula. At the same rate it is "},{"text":"higher","bold":true},{"text":" than the compound value, because simple interest discounts later payments less."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Example 1.","bold":true},{"text":" ₦10,000, ₦20,000, ₦30,000, ₦40,000 at the ends of years 1 to 4, at 10%. ä_4| = 3.4869, 4v^4 = 2.7321. (Ia)_4| = (3.4869 - 2.7321)/0.1 = 7.5480. PV = "},{"text":"₦75,480","bold":true},{"text":". Check: 10,000(1 × 0.9091 + 2 × 0.8264 + 3 × 0.7513 + 4 × 0.6830) agrees."}]},{"type":"paragraph","text":[{"text":"Example 2.","bold":true},{"text":" ₦40,000, ₦30,000, ₦20,000, ₦10,000 at 10%: (Da)_4| = (4 - 3.1699)/0.1 = 8.3013. PV = "},{"text":"₦83,013","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 3 (arithmetic).","bold":true},{"text":" ₦50,000 at time 1, rising by ₦10,000 a year, 4 payments, 10%: 50,000 × 3.1699 + 10,000 × (3.1699 - 2.7321)/0.1 = 158,493 + 43,781 = "},{"text":"₦202,274","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 4 (geometric).","bold":true},{"text":" ₦200,000 at time 1, rising 4% a year, 5 payments, 10%: (1.04/1.1)^5 = 0.755446; PV = 200,000 × (1 - 0.755446)/0.06 = "},{"text":"₦815,181","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Example 5 (simple interest).","bold":true},{"text":" a_3| at 10% simple: 1/1.1 + 1/1.2 + 1/1.3 = 0.9091 + 0.8333 + 0.7692 = "},{"text":"2.5117","bold":true},{"text":"; at 10% compound a_3| = 2.4869, so the simple value is higher."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: (Ia)_n| has ä_n| (the due factor) in its formula; (Da)_n| has a_n| and n. Do not swap them."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Annuity = regular payments. Immediate (ordinary, in arrears) pays at period ends; due (in advance) pays at period starts."}]},{"text":[{"text":"a_n| = (1 - v^n)/i; s_n| = [(1 + i)^n - 1]/i; ä_n| = (1 - v^n)/d; s̈_n| = [(1 + i)^n - 1]/d."}]$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 32, $study_guide$},{"text":[{"text":"ä_n| = (1 + i)a_n| = 1 + a_(n-1)|; s_(n+1)| = s̈_n| + 1; ä_n| > a_n|."}]},{"text":[{"text":"Two dots = acceleration (in advance); bar = continuous; m| = deferred m periods."}]},{"text":[{"text":"Loan instalment = Loan/a_n|; fund deposit = Target/s_n|; outstanding loan = X × a_(remaining)|."}]},{"text":[{"text":"m|a_n| = v^m a_n| = a_(m+n)| - a_m|; perpetuity 1/i in arrears, 1/d in advance."}]},{"text":[{"text":"Different payment and interest periods: find the effective rate per payment period first."}]},{"text":[{"text":"a^(m)_n| = (1 - v^n)/i^(m); ā_n| = (1 - v^n)/δ."}]},{"text":[{"text":"(Ia)_n| = (ä_n| - n v^n)/i; (Da)_n| = (n - a_n|)/i; geometric [1 - ((1 + k)/(1 + i))^n]/(i - k)."}]},{"text":[{"text":"Certain annuities run a fixed term; life (contingent) annuities stop at death."}]}]}],"theory":{"itemId":"6c7131aa-8859-5ab1-853e-11d82c02ed25","question":[{"type":"paragraph","text":[{"text":"A company promises a manager ₦400,000 at the end of each year for 12 years, the first payment one year after she retires in 5 years' time. It funds this with 5 equal payments at the "},{"text":"beginning","bold":true},{"text":" of each year over the 5 years before retirement. At 7% effective, find the annual funding payment."}]}]},"practice":[{"topic":"Annuities and Annuity Functions","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"1871811f-78c9-57e1-980e-e0e29fb463ab","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"An insurer covers 20,000 similar okada riders in Lagos. Past experience shows 1.5% of riders make a claim each year, with an average claim of ₦250,000. Ignoring expenses and profit, find (a) the expected claim cost per rider and (b) the total expected claims. (c) Why is this prediction reliable?"},"answer":{"kind":"model_answer","itemId":"6ca95bfe-82d0-5b9b-bc3c-2421e556581c","sourceKey":"guide-answer:1","payload":{"body":"• (a) 1.5% = 0.015. Expected cost per rider = 0.015 × ₦250,000 = ₦3,750.\n• (b) Total = 20,000 × ₦3,750 = ₦75,000,000.\n• (c) By the law of large numbers, a large pool of similar, independent risks gives a stable claim proportion, so total claims are predictable."}}},{"kind":"theory_question","itemId":"09606d73-a9a7-537f-8892-586f175d7f31","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"Arrange in time order, earliest first: founding of the Institute of Actuaries; Halley's Breslau table; Graunt's observations; founding of the Equitable Society. Give the year of each."},"answer":{"kind":"model_answer","itemId":"23d25f93-c231-58a2-b91b-83da1bcda394","sourceKey":"guide-answer:2","payload":{"body":"Graunt's observations (1662), Halley's Breslau table (1693), Equitable Society (1762), Institute of Actuaries (1848). Check each pair: 1662 < 1693 < 1762 < 1848."}}},{"kind":"theory_question","itemId":"91ec30ca-0cb2-5a01-be7f-30fc2372ece4","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"In a life table l_40 = 90,000, q_40 = 0.003 and q_41 = 0.004. Find l_41, d_41, l_42 and _2p_40."},"answer":{"kind":"model_answer","itemId":"9e0ec73a-457d-57c3-8e96-eba0d9fedf83","sourceKey":"guide-answer:3","payload":{"body":"• l_41 = 90,000 × (1 - 0.003) = 90,000 × 0.997 = 89,730.\n• d_41 = l_41 × q_41 = 89,730 × 0.004 = 358.92.\n• l_42 = 89,730 - 358.92 = 89,371.08.\n• _2p_40 = 89,371.08/90,000 = 0.993012 (check: 0.997 × 0.996 = 0.993012). So _2q_40 = 0.006988."}}},{"kind":"theory_question","itemId":"8368a089-9a1b-5585-8838-55f0fc3e0e42","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"An insurer covers 400 Lagos shop owners against burglary for one year. The probability of a claim is 0.02 per shop and the average claim is ₦500,000 (at most one claim each). It adds a 30% loading. Find (a) the risk premium per shop, (b) the gross premium per shop, (c) the expected loss ratio if claims come in as expected."},"answer":{"kind":"model_answer","itemId":"3efc60c8-0f4e-5452-97bf-11ec780a3e85","sourceKey":"guide-answer:4","payload":{"body":"• (a) 0.02 × ₦500,000 = ₦10,000.\n• (b) ₦10,000 × 1.30 = ₦13,000.\n• (c) Expected claims = 400 × ₦10,000 = ₦4,000,000; premiums = 400 × ₦13,000 = ₦5,200,000; loss ratio = 4,000,000 / 5,200,000 = 76.92% (to 2 decimal places)."}}},{"kind":"theory_question","itemId":"9a35d314-f734-5003-9bae-9f1da719e5c9","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"A nominal rate of interest is 8% per annum convertible quarterly. Find (a) the equivalent effective annual rate of interest, (b) the force of interest, and (c) the accumulated value of ₦100,000 after 3 years. Give rates to 4 decimal places and money to the nearest kobo."},"answer":{"kind":"model_answer","itemId":"a9213c87-8d73-59cd-876b-c82c5544b569","sourceKey":"guide-answer:5","payload":{"body":"(a) Quarterly rate = 0.08/4 = 0.02. i = (1.02)^4 − 1 = 1.082432 − 1 = 0.0824 (8.24%).\n(b) δ = ln(1 + i) = ln 1.082432 = 4 ln 1.02 = 0.0792.\n(c) 3 years = 12 quarters: 100,000 × 1.02^12 = 100,000 × 1.26824179 = ₦126,824.18."}}},{"kind":"theory_question","itemId":"9183b89f-38d6-54e3-a6cf-d7d739aac07b","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"A debt of ₦200,000 is due at time 3. It is to be settled by X at time 1 and X at time 2. At 10% per annum effective, find X."},"answer":{"kind":"model_answer","itemId":"fa271e96-df30-53f0-b45b-2f5955a97cdf","sourceKey":"guide-answer:6","payload":{"body":"Equation of value at time 0: X(1.1^(−1) + 1.1^(−2)) = 200,000 × 1.1^(−3). Left factor = 0.909091 + 0.826446 = 1.735537. Right side = 200,000 × 0.751315 = 150,262.96. X = 150,262.96 ÷ 1.735537 = ₦86,580 (nearest naira)."}}},{"kind":"theory_question","itemId":"6c7131aa-8859-5ab1-853e-11d82c02ed25","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"A company promises a manager ₦400,000 at the end of each year for 12 years, the first payment one year after she retires in 5 years' time. It funds this with 5 equal payments at the beginning of each year over the 5 years before retirement. At 7% effective$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acs101', 33, $study_guide$, find the annual funding payment."},"answer":{"kind":"model_answer","itemId":"c2ea8925-31e6-5f1f-9f1b-a8f2b48ddadf","sourceKey":"guide-answer:7","payload":{"body":"1. Value of the pension at retirement (time 5): 400,000 × a_12| = 400,000 × 7.942686 = ₦3,177,075.\n2. Bring it to today: 3,177,075 × 1.07^-5 = 3,177,075 × 0.712986 = ₦2,265,210.\n3. Funding is an annuity-due of 5 payments: ä_5| = (1 - 1.07^-5)/d = 4.387211.\n4. X = 2,265,210/4.387211 = ₦516,321 (to the nearest naira, using unrounded factors)."}}}]}$study_guide$);
